    BaniLine(id = "anand-sahib-16", gurmukhi = "ਨਾਮੁ ਜਿਨ ਕੈ ਮਨਿ ਵਸਿਆ; ਵਾਜੇ ਸਬਦ ਘਨੇਰੇ ॥", transliteration = "naam jin kai man vsiaa; vaaje sabad ghnere ||", translation = "The divine melody of the Shabad vibrates for those, within whose minds the Naam abides.", hindi = "नामु जिन कै मनि वसिआ; वाजे सबद घनेरे ॥", punjabi = "ਜਿਨ੍ਹਾਂ ਬੰਦਿਆਂ ਦੇ ਮਨ ਵਿਚ (ਤੇਰਾ) ਨਾਮ ਵੱਸਦਾ ਹੈ (ਉਹਨਾਂ ਦੇ ਅੰਦਰ, ਮਾਨੋ,) ਬੇਅੰਤ ਸਾਜ਼ਾਂ ਦੀਆਂ (ਮਿਲਵੀਆਂ) ਸੁਰਾਂ ਵੱਜਣ ਲੱਗ ਪੈਂਦੀਆਂ ਹਨ (ਭਾਵ, ਉਹਨਾਂ ਦੇ ਮਨ ਵਿਚ ਉਹ ਖ਼ੁਸ਼ੀ ਤੇ ਚਾਉ ਪੈਦਾ ਹੁੰਦਾ ਹੈ ਜੋ ਕਈ ਸਾਜ਼ਾਂ ਦਾ ਮਿਲਵਾਂ ਰਾਗ ਸੁਣ ਕੇ ਪੈਦਾ ਹੁੰਦਾ ਹੈ)।", wordMeaning = "ਜਿਨ ਕੈ ਮਨਿ = ਜਿਨ੍ਹਾਂ ਦੇ ਮਨ ਵਿਚ। ਵਾਜੇ = ਵੱਜਦੇ ਹਨ। ਸਬਦ = ਸਾਜਾਂ ਦੇ ਆਵਾਜ਼, ਰਾਗਾਂ ਦੀਆਂ ਸੁਰਾਂ। ਘਨੇਰੇ = ਬੇਅੰਤ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-17", gurmukhi = "ਕਹੈ ਨਾਨਕੁ. ਸਚੇ ਸਾਹਿਬ; ਕਿਆ ਨਾਹੀ. ਘਰਿ ਤੇਰੈ ॥੩॥", transliteration = "kahai naanak. sche saahib; kiaa naahee. ghar terai ||3||", translation = "Says Nanak, O my True Lord and Master, what is there which is not in Your home? ||3||", hindi = "कहै नानकु. सचे साहिब; किआ नाही. घरि तेरै ॥३॥", punjabi = "ਨਾਨਕ ਆਖਦਾ ਹੈ ਕਿ ਹੇ ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲੇ ਮਾਲਕ! ਤੇਰੇ ਘਰ ਵਿਚ ਕਿਸੇ ਸ਼ੈ ਦਾ ਘਾਟਾ ਨਹੀਂ ਹੈ (ਤੇ, ਮੈਂ ਤੇਰੇ ਦਰ ਤੋਂ ਆਨੰਦ ਦਾ ਦਾਨ ਮੰਗਦਾ ਹਾਂ) ॥੩॥", wordMeaning = "ਸਚੇ = ਹੇ ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲੇ! ॥੩॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-18", gurmukhi = "ਸਾਚਾ ਨਾਮੁ; ਮੇਰਾ ਆਧਾਰੋ ॥", transliteration = "saachaa naam; meraa aadhaaro ||", translation = "The True Name is my only support.", hindi = "साचा नामु; मेरा आधारो ॥", punjabi = "(ਪ੍ਰਭੂ ਦੀ ਮੇਹਰ ਨਾਲ ਉਸ ਦਾ) ਸਦਾ-ਥਿਰ ਰਹਿਣ ਵਾਲਾ ਨਾਮ ਮੇਰੀ ਜ਼ਿੰਦਗੀ ਦਾ ਆਸਰਾ (ਬਣ ਗਿਆ) ਹੈ।", wordMeaning = "ਆਧਾਰੋ = ਆਸਰਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-19", gurmukhi = "ਸਾਚੁ ਨਾਮੁ ਅਧਾਰੁ ਮੇਰਾ; ਜਿਨਿ ਭੁਖਾ ਸਭਿ ਗਵਾਈਆ ॥", transliteration = "saach naam adhaar meraa; jin bhukhaa sabh gvaaeeaa ||", translation = "The True Name is my only support; it satisfies all hunger.", hindi = "साचु नामु अधारु मेरा; जिनि भुखा सभि गवाईआ ॥", punjabi = "ਉਹ ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲਾ ਨਾਮ ਮੇਰੀ ਜ਼ਿੰਦਗੀ ਦਾ ਆਸਰਾ ਬਣ ਗਿਆ) ਹੈ, ਜਿਸ (ਹਰਿ-ਨਾਮ) ਨੇ ਮੇਰੇ ਸਾਰੇ ਲਾਲਚ ਦੂਰ ਕਰ ਦਿੱਤੇ ਹਨ।", wordMeaning = "ਜਿਨਿ = ਜਿਸ (ਨਾਮ) ਨੇ। ਭੁਖ = ਲਾਲਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-20", gurmukhi = "ਕਰਿ ਸਾਂਤਿ ਸੁਖ ਮਨਿ ਆਇ ਵਸਿਆ; ਜਿਨਿ ਇਛਾ ਸਭਿ ਪੁਜਾਈਆ ॥", transliteration = "kar saant sukh man aai vsiaa; jin ichhaa sabh pujaaeeaa ||", translation = "It has brought peace and tranquility to my mind; it has fulfilled all my desires.", hindi = "करि सांति सुख मनि आइ वसिआ; जिनि इछा सभि पुजाईआ ॥", punjabi = "ਜੋ ਹਰਿ-ਨਾਮ (ਮੇਰੇ ਅੰਦਰ) ਸ਼ਾਂਤੀ ਤੇ ਸੁਖ ਪੈਦਾ ਕਰਕੇ ਮੇਰੇ ਮਨ ਵਿਚ ਆ ਟਿਕਿਆ ਹੈ, ਜਿਸ (ਹਰਿ-ਨਾਮ) ਨੇ ਮੇਰੇ ਮਨ ਦੀਆਂ ਸਾਰੀਆਂ ਕਾਮਨਾਂ ਪੂਰੀਆਂ ਕਰ ਦਿੱਤੀਆਂ ਹਨ।", wordMeaning = "ਕਰਿ = (ਪੈਦਾ) ਕਰ ਕੇ। ਮਨਿ = ਮਨ ਵਿਚ। ਇਛਾ = ਮਨ ਦੀਆਂ ਕਾਮਨਾਂ। ਸਭਿ = ਸਾਰੀਆਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-21", gurmukhi = "ਸਦਾ ਕੁਰਬਾਣੁ ਕੀਤਾ ਗੁਰੂ ਵਿਟਹੁ; ਜਿਸ ਦੀਆ ਏਹਿ ਵਡਿਆਈਆ ॥", transliteration = "sadaa kurbaan keetaa guroo vitah; jis deeaa eh vdiaaeeaa ||", translation = "I am forever a sacrifice to the Guru, who possesses such glorious greatness.", hindi = "सदा कुरबाणु कीता गुरू विटहु; जिस दीआ एहि वडिआईआ ॥", punjabi = "ਮੈਂ (ਆਪਣੇ ਆਪ ਨੂੰ) ਆਪਣੇ ਗੁਰੂ ਤੋਂ ਸਦਕੇ ਕਰਦਾ ਹਾਂ, ਕਿਉਂਕਿ ਇਹ ਸਾਰੀਆਂ ਬਰਕਤਾਂ ਗੁਰੂ ਦੀਆਂ ਹੀ ਹਨ।", wordMeaning = "ਕੁਰਬਾਣੁ = ਸਦਕੇ। ਵਿਟਹੁ = ਤੋਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-22", gurmukhi = "ਕਹੈ ਨਾਨਕੁ. ਸੁਣਹੁ ਸੰਤਹੁ; ਸਬਦਿ ਧਰਹੁ ਪਿਆਰੋ ॥", transliteration = "kahai naanak. sunah santah; sabad dharah piaaro ||", translation = "Says Nanak, listen, O Saints; enshrine love for the Shabad.", hindi = "कहै नानकु. सुणहु संतहु; सबदि धरहु पिआरो ॥", punjabi = "ਨਾਨਕ ਆਖਦਾ ਹੈ ਕਿ ਹੇ ਸੰਤ ਜਨੋ! (ਗੁਰੂ ਦਾ ਸ਼ਬਦ) ਸੁਣੋ, ਗੁਰੂ ਦੇ ਸ਼ਬਦ ਵਿਚ ਪਿਆਰ ਬਣਾਓ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-23", gurmukhi = "ਸਾਚਾ ਨਾਮੁ; ਮੇਰਾ ਆਧਾਰੋ ॥੪॥", transliteration = "saachaa naam; meraa aadhaaro ||4||", translation = "The True Name is my only support. ||4||", hindi = "साचा नामु; मेरा आधारो ॥४॥", punjabi = "(ਸਤਿਗੁਰੂ ਦੀ ਮੇਹਰ ਨਾਲ ਹੀ ਪ੍ਰਭੂ ਦਾ) ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲਾ ਨਾਮ ਮੇਰੀ ਜ਼ਿੰਦਗੀ ਦਾ ਆਸਰਾ (ਬਣ ਗਿਆ) ਹੈ ॥੪॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-24", gurmukhi = "ਵਾਜੇ ਪੰਚ ਸਬਦ; ਤਿਤੁ ਘਰਿ ਸਭਾਗੈ ॥", transliteration = "vaaje panch sabad; tit ghar sbhaagai ||", translation = "The Panch Shabad, the five primal sounds, vibrate in that blessed house.", hindi = "वाजे पंच सबद; तितु घरि सभागै ॥", punjabi = "ਉਸ ਭਾਗਾਂ ਵਾਲੇ (ਹਿਰਦੇ-) ਘਰ ਵਿਚ (ਮਾਨੋ) ਪੰਜ ਕਿਸਮਾਂ ਦੇ ਸਾਜ਼ਾਂ ਦੀਆਂ ਮਿਲਵੀਆਂ ਸੁਰਾਂ ਵੱਜ ਪੈਂਦੀਆਂ ਹਨ,", wordMeaning = "ਵਾਜੇ = ਵੱਜਦੇ ਹਨ, ਵੱਜੇ ਹਨ। ਪੰਚ ਸਬਦ = ਪੰਜ ਕਿਸਮਾਂ ਦੇ ਸਾਜ਼ਾਂ ਦੀਆਂ ਮਿਲਵੀਆਂ ਸੁਰਾਂ। ਤਿਤੁ = ਉਸ ਵਿਚ। ਤਿਤੁ ਘਰਿ = ਉਸ ਹਿਰਦੇ-ਘਰਿ ਵਿਚ। ਸਭਾਗੈ = ਭਾਗਾਂ ਵਾਲੇ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-25", gurmukhi = "ਘਰਿ ਸਭਾਗੈ ਸਬਦ ਵਾਜੇ; ਕਲਾ ਜਿਤੁ ਘਰਿ ਧਾਰੀਆ ॥", transliteration = "ghar sbhaagai sabad vaaje; klaa jit ghar dhaareeaa ||", translation = "In that blessed house, the Shabad vibrates; He infuses His almighty power into it.", hindi = "घरि सभागै सबद वाजे; कला जितु घरि धारीआ ॥", punjabi = "ਜਿਸ (ਹਿਰਦੇ-) ਘਰ ਵਿਚ (ਹੇ ਪ੍ਰਭੂ! ਤੂੰ) ਸੱਤਿਆ ਪਾਈ ਹੈ, ਉਸ ਭਾਗਾਂ ਵਾਲੇ (ਹਿਰਦੇ-) ਘਰ ਵਿਚ (ਮਾਨੋ) ਪੰਜ ਕਿਸਮਾਂ ਦੇ ਸਾਜ਼ਾਂ ਦੀਆਂ ਮਿਲਵੀਆਂ ਸੁਰਾਂ ਵੱਜ ਪੈਂਦੀਆਂ ਹਨ (ਭਾਵ, ਉਸ ਹਿਰਦੇ ਵਿਚ ਪੂਰਨ ਆਨੰਦ ਬਣ ਜਾਂਦਾ ਹੈ),", wordMeaning = "ਤਿਤੁ ਸਭਾਗੈ ਘਰਿ = ਉਸ ਭਾਗਾਂ ਵਾਲੇ (ਹਿਰਦੇ-) ਘਰ ਵਿਚ। ਕਲਾ = ਸੱਤਿਆ। ਜਿਤੁ ਘਰਿ = ਜਿਸ ਘਰ ਵਿਚ। ਧਾਰੀਆ = ਤੂੰ ਪਾਈ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-26", gurmukhi = "ਪੰਚ ਦੂਤ ਤੁਧੁ ਵਸਿ ਕੀਤੇ; ਕਾਲੁ ਕੰਟਕੁ ਮਾਰਿਆ ॥", transliteration = "panch doot tudh vas keete; kaal kantak maariaa ||", translation = "Through You, we subdue the five demons of desire, and slay Death, the torturer.", hindi = "पंच दूत तुधु वसि कीते; कालु कंटकु मारिआ ॥", punjabi = "(ਹੇ ਪ੍ਰਭੂ!) ਉਸ ਦੇ ਪੰਜੇ ਕਾਮਾਦਿਕ ਵੈਰੀ ਤੂੰ ਕਾਬੂ ਵਿਚ ਕਰ ਦੇਂਦਾ ਹੈਂ, ਤੇ ਡਰਾਣ ਵਾਲਾ ਕਾਲ (ਭਾਵ, ਮੌਤ ਦਾ ਡਰ) ਦੂਰ ਕਰ ਦੇਂਦਾ ਹੈਂ।", wordMeaning = "ਪੰਚ ਦੂਤ = ਕਾਮਾਦਿਕ ਪੰਜ ਵੈਰੀ। ਕੰਟਕੁ = ਕੰਡਾ। ਕੰਟਕੁ ਕਾਲੁ = ਡਰਾਉਣਾ ਕਾਲ, ਮੌਤ ਦਾ ਡਰ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-27", gurmukhi = "ਧੁਰਿ ਕਰਮਿ ਪਾਇਆ ਤੁਧੁ. ਜਿਨ ਕਉ; ਸਿ. ਨਾਮਿ ਹਰਿ ਕੈ ਲਾਗੇ ॥", transliteration = "dhur karam paaiaa tudh. jin kau; si. naam har kai laage ||", translation = "Those who have such pre-ordained destiny are attached to the Lord's Name.", hindi = "धुरि करमि पाइआ तुधु. जिन कउ; सि. नामि हरि कै लागे ॥", punjabi = "ਪਰ ਸਿਰਫ਼ ਉਹੀ ਮਨੁੱਖ ਹਰਿ-ਨਾਮ ਵਿਚ ਜੁੜਦੇ ਹਨ ਜਿਨ੍ਹਾਂ ਦੇ ਭਾਗਾਂ ਵਿਚ ਤੂੰ ਧੁਰ ਤੋਂ ਹੀ ਆਪਣੀ ਮੇਹਰ ਨਾਲ (ਸਿਮਰਨ ਦਾ ਲੇਖ ਲਿਖ ਕੇ) ਰੱਖ ਦਿੱਤਾ ਹੈ।", wordMeaning = "ਧੁਰਿ = ਧੁਰ ਤੋਂ। ਕਰਮਿ = ਮੇਹਰ ਨਾਲ। ਸਿ = ਸੇ, ਉਹ ਬੰਦੇ। ਨਾਮਿ = ਨਾਮ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-28", gurmukhi = "ਕਹੈ ਨਾਨਕੁ. ਤਹ ਸੁਖੁ ਹੋਆ; ਤਿਤੁ ਘਰਿ ਅਨਹਦ ਵਾਜੇ ॥੫॥", transliteration = "kahai naanak. tah sukh hoaa; tit ghar anahad vaaje ||5||", translation = "Says Nanak, they are at peace, and the unstruck sound current vibrates within their homes. ||5||", hindi = "कहै नानकु. तह सुखु होआ; तितु घरि अनहद वाजे ॥५॥", punjabi = "ਨਾਨਕ ਆਖਦਾ ਹੈ ਕਿ ਉਸ ਹਿਰਦੇ-ਘਰ ਵਿਚ ਸੁਖ ਪੈਦਾ ਹੁੰਦਾ ਹੈ, ਉਸ ਹਿਰਦੇ ਵਿਚ (ਮਾਨੋ) ਇਕ-ਰਸ (ਵਾਜੇ) ਵੱਜਦੇ ਹਨ ॥੫॥", wordMeaning = "ਅਨਹਦ = ਅਨ-ਹਦ, ਬਿਨਾ ਵਜਾਏ ਵੱਜਣ ਵਾਲੇ, ਇਕ-ਰਸ, ਲਗਾਤਾਰ ॥੫॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-29", gurmukhi = "ਸਾਚੀ ਲਿਵੈ ਬਿਨੁ; ਦੇਹ ਨਿਮਾਣੀ ॥", transliteration = "saachee livai bin; deh nimaanee ||", translation = "Without the true love of devotion, the body is without honor.", hindi = "साची लिवै बिनु; देह निमाणी ॥", punjabi = "ਸਦਾ-ਥਿਰ ਪ੍ਰਭੂ ਦੇ ਚਰਨਾਂ ਦੀ ਲਗਨ (ਦੇ ਆਨੰਦ) ਤੋਂ ਬਿਨਾ ਇਹ (ਮਨੁੱਖਾ) ਸਰੀਰ ਨਿਆਸਰਾ ਜੇਹਾ ਹੀ ਰਹਿੰਦਾ ਹੈ।", wordMeaning = "ਸਾਚੀ ਲਿਵ = ਸੱਚੀ ਲਗਨ, ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲੀ ਲਗਨ, ਸਦਾ-ਥਿਰ ਪ੍ਰਭੂ ਨਾਲ ਪ੍ਰੀਤ। ਦੇਹ = ਸਰੀਰ। ਨਿਮਾਣੀ = ਨਿਆਸਰੀ ਜੇਹੀ, ਹੌਲੇ ਮੇਲ ਦੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-30", gurmukhi = "ਦੇਹ ਨਿਮਾਣੀ. ਲਿਵੈ ਬਾਝਹੁ; ਕਿਆ ਕਰੇ ਵੇਚਾਰੀਆ ॥", transliteration = "deh nimaanee. livai baajhah; kiaa kre vechaareeaa ||", translation = "The body is dishonored without devotional love; what can the poor wretches do?", hindi = "देह निमाणी. लिवै बाझहु; किआ करे वेचारीआ ॥", punjabi = "ਪ੍ਰਭੂ-ਚਰਨਾਂ ਦੀ ਪ੍ਰੀਤ ਤੋਂ ਬਿਨਾ ਨਿਆਸਰਾ ਹੋਇਆ ਹੋਇਆ ਇਹ ਸਰੀਰ ਜੋ ਕੁਝ ਭੀ ਕਰਦਾ ਹੈ ਨਕਾਰੇ ਕੰਮ ਹੀ ਕਰਦਾ ਹੈ।", wordMeaning = "ਕਿਆ ਕਰੇ = ਕੀਹ ਕਰਦੀ ਹੈ? ਜੋ ਕੁਝ ਕਰਦੀ ਹੈ ਨਕਾਰੇ ਕੰਮ ਹੀ ਕਰਦੀ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
