    BaniLine(id = "anand-sahib-42", gurmukhi = "ਗੁਰ ਪਰਸਾਦੀ. ਮਨੁ ਭਇਆ ਨਿਰਮਲੁ; ਜਿਨਾ ਭਾਣਾ ਭਾਵਏ ॥", transliteration = "gur parsaadee. man bhaiaa niramal; jinaa bhaanaa bhaavae ||", translation = "By Guru's Grace, the mind becomes immaculate and pure, for those who follow God's Will.", hindi = "गुर परसादी. मनु भइआ निरमलु; जिना भाणा भावए ॥", punjabi = "(ਇਸ ਤਰ੍ਹਾਂ ਤੇਰੀ ਮੇਹਰ ਨਾਲ) ਜਿਨ੍ਹਾਂ ਨੂੰ ਤੇਰੀ ਰਜ਼ਾ ਪਿਆਰੀ ਲੱਗਣ ਲੱਗ ਪੈਂਦੀ ਹੈ, ਗੁਰੂ ਦੀ ਕਿਰਪਾ ਨਾਲ ਉਹਨਾਂ ਦਾ ਮਨ ਪਵਿਤ੍ਰ ਹੋ ਜਾਂਦਾ ਹੈ (ਤੇ ਉਹ ਆਤਮਕ ਆਨੰਦ ਮਾਣਦੇ ਹਨ,", wordMeaning = "ਭਾਣਾ = ਰਜ਼ਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-43", gurmukhi = "ਕਹੈ ਨਾਨਕੁ. ਜਿਸੁ ਦੇਹਿ ਪਿਆਰੇ; ਸੋਈ ਜਨੁ ਪਾਵਏ ॥੮॥", transliteration = "kahai naanak. jis deh piaare; soee jan paavae ||8||", translation = "Says Nanak, he alone receives it, unto whom You give it, O Beloved Lord. ||8||", hindi = "कहै नानकु. जिसु देहि पिआरे; सोई जनु पावए ॥८॥", punjabi = "(ਪਰ) ਨਾਨਕ ਆਖਦਾ ਹੈ ਕਿ (ਹੇ ਪ੍ਰਭੂ!) ਜਿਸ ਨੂੰ ਤੂੰ (ਆਤਮਕ ਆਨੰਦ ਦੀ ਦਾਤਿ) ਬਖ਼ਸ਼ਦਾ ਹੈਂ ਉਹੀ ਇਸ ਨੂੰ ਮਾਣ ਸਕਦਾ ਹੈ ॥੮॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-44", gurmukhi = "ਆਵਹੁ ਸੰਤ ਪਿਆਰਿਹੋ; ਅਕਥ ਕੀ ਕਰਹ ਕਹਾਣੀ ॥", transliteration = "aavah sant piaariho; akath kee karah khaanee ||", translation = "Come, Beloved Saints, let us speak the Unspoken Speech of the Lord.", hindi = "आवहु संत पिआरिहो; अकथ की करह कहाणी ॥", punjabi = "ਹੇ ਪਿਆਰੇ ਸੰਤ ਜਨੋ! ਆਓ, ਅਸੀਂ (ਰਲ ਕੇ) ਬੇਅੰਤ ਗੁਣਾਂ ਵਾਲੇ ਪਰਮਾਤਮਾ ਦੀਆਂ ਸਿਫ਼ਤ-ਸਾਲਾਹ ਦੀਆਂ ਗੱਲਾਂ ਕਰੀਏ,", wordMeaning = "ਅਕਥ = ਜਿਸ ਦੇ ਸਾਰੇ ਗੁਣ ਬਿਆਨ ਨ ਕੀਤੇ ਜਾ ਸਕਣ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-45", gurmukhi = "ਕਰਹ ਕਹਾਣੀ ਅਕਥ ਕੇਰੀ; ਕਿਤੁ ਦੁਆਰੈ ਪਾਈਐ ॥", transliteration = "karah khaanee akath keree; kit duaarai paaeeai ||", translation = "How can we speak the Unspoken Speech of the Lord? Through which door will we find Him?", hindi = "करह कहाणी अकथ केरी; कितु दुआरै पाईऐ ॥", punjabi = "ਉਸ ਪ੍ਰਭੂ ਦੀਆਂ ਕਹਾਣੀਆਂ ਸੁਣੀਏ ਸੁਣਾਈਏ ਜਿਸ ਦੇ ਗੁਣ ਬਿਆਨ ਤੋਂ ਪਰੇ ਹਨ। (ਪਰ ਜੇ ਤੁਸੀ ਪੁੱਛੋ ਕਿ) ਉਹ ਪ੍ਰਭੂ ਕਿਸ ਤਰੀਕੇ ਨਾਲ ਮਿਲਦਾ ਹੈ?", wordMeaning = "ਕਰਹ = ਅਸੀਂ ਕਰੀਏ। ਕਿਤੁ ਦੁਆਰੈ = ਕਿਸ ਵਸੀਲੇ ਨਾਲ? ਕੇਰੀ = ਦੀ", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-46", gurmukhi = "ਤਨੁ ਮਨੁ ਧਨੁ ਸਭੁ. ਸਉਪਿ ਗੁਰ ਕਉ; ਹੁਕਮਿ ਮੰਨਿਐ ਪਾਈਐ ॥", transliteration = "tan man dhan sabh. saup gur kau; hukam manniai paaeeai ||", translation = "Surrender body, mind, wealth, and everything to the Guru; obey the Order of His Will, and you will find Him.", hindi = "तनु मनु धनु सभु. सउपि गुर कउ; हुकमि मंनिऐ पाईऐ ॥", punjabi = "(ਤਾਂ ਉੱਤਰ ਇਹ ਹੈ ਕਿ ਆਪਣਾ ਆਪ ਮਾਇਆ ਦੇ ਹਵਾਲੇ ਕਰਨ ਦੇ ਥਾਂ) ਆਪਣਾ ਤਨ ਮਨ ਧਨ ਸਭ ਕੁਝ ਗੁਰੂ ਦੇ ਹਵਾਲੇ ਕਰੋ (ਇਸ ਤਰ੍ਹਾਂ) ਜੇ ਗੁਰੂ ਦਾ ਹੁਕਮ ਮਿੱਠਾ ਲੱਗਣ ਲੱਗ ਪਏ ਤਾਂ ਪਰਮਾਤਮਾ ਮਿਲ ਪੈਂਦਾ ਹੈ।", wordMeaning = "ਸਉਪਿ = ਹਵਾਲੇ ਕਰ ਦਿਹੁ। ਹੁਕਮਿ ਮੰਨਿਐ = ਜੇ (ਪ੍ਰਭੂ ਦਾ) ਹੁਕਮ (ਸਿਰ ਮੱਥੇ ਤੇ) ਮੰਨ ਲਿਆ ਜਾਏ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-47", gurmukhi = "ਹੁਕਮੁ ਮੰਨਿਹੁ ਗੁਰੂ ਕੇਰਾ; ਗਾਵਹੁ ਸਚੀ ਬਾਣੀ ॥", transliteration = "hukam mannih guroo keraa; gaavah schee baanee ||", translation = "Obey the Hukam of the Guru's Command, and sing the True Word of His Bani.", hindi = "हुकमु मंनिहु गुरू केरा; गावहु सची बाणी ॥", punjabi = "(ਸੋ, ਸੰਤ ਜਨੋ!) ਗੁਰੂ ਦੇ ਹੁਕਮ ਉੱਤੇ ਤੁਰੋ ਤੇ ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲੇ ਪ੍ਰਭੂ ਦੀ ਸਿਫ਼ਤ-ਸਾਲਾਹ ਦੀ ਬਾਣੀ ਗਾਇਆ ਕਰੋ।", wordMeaning = "ਕੇਰਾ = ਦਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-48", gurmukhi = "ਕਹੈ ਨਾਨਕੁ. ਸੁਣਹੁ ਸੰਤਹੁ; ਕਥਿਹੁ. ਅਕਥ ਕਹਾਣੀ ॥੯॥", transliteration = "kahai naanak. sunah santah; kthih. akath khaanee ||9||", translation = "Says Nanak, listen, O Saints, and speak the Unspoken Speech of the Lord. ||9||", hindi = "कहै नानकु. सुणहु संतहु; कथिहु. अकथ कहाणी ॥९॥", punjabi = "ਨਾਨਕ ਆਖਦਾ ਹੈ ਕਿ ਹੇ ਸੰਤ ਜਨੋ ਸੁਣੋ, (ਉਸ ਨੂੰ ਮਿਲਣ ਦਾ ਅਤੇ ਆਤਮਕ ਆਨੰਦ ਮਾਣਨ ਦਾ ਸਹੀ ਰਸਤਾ ਇਹੀ ਹੈ ਕਿ) ਉਸ ਅਕੱਥ ਪ੍ਰਭੂ ਦੀਆਂ ਕਹਾਣੀਆਂ ਕਰਿਆ ਕਰੋ ॥੯॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-49", gurmukhi = "ਏ ਮਨ ਚੰਚਲਾ; ਚਤੁਰਾਈ ਕਿਨੈ. ਨ ਪਾਇਆ ॥", transliteration = "e man chanchlaa; chturaaee kinai. na paaiaa ||", translation = "O fickle mind, through cleverness, no one has found the Lord.", hindi = "ए मन चंचला; चतुराई किनै. न पाइआ ॥", punjabi = "ਹੇ ਚੰਚਲ ਮਨ! ਚਲਾਕੀਆਂ ਨਾਲ ਕਿਸੇ ਨੇ ਭੀ (ਆਤਮਕ ਆਨੰਦ) ਹਾਸਲ ਨਹੀਂ ਕੀਤਾ।", wordMeaning = "ਕਿਨੈ = ਕਿਸੇ ਮਨੁੱਖ ਨੇ ਭੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-50", gurmukhi = "ਚਤੁਰਾਈ. ਨ ਪਾਇਆ ਕਿਨੈ; ਤੂ ਸੁਣਿ ਮੰਨ ਮੇਰਿਆ ॥", transliteration = "chaturaaee. na paaiaa kinai; too sun mann meriaa ||", translation = "Through cleverness, no one has found Him; listen, O my mind.", hindi = "चतुराई. न पाइआ किनै; तू सुणि मंन मेरिआ ॥", punjabi = "ਹੇ ਮੇਰੇ ਮਨ! ਤੂੰ (ਧਿਆਨ ਨਾਲ) ਸੁਣ ਲੈ ਕਿ ਕਿਸੇ ਜੀਵ ਨੇ ਭੀ ਚਤੁਰਾਈ ਨਾਲ (ਪਰਮਾਤਮਾ ਦੇ ਮਿਲਾਪ ਦਾ ਆਨੰਦ) ਪ੍ਰਾਪਤ ਨਹੀਂ ਕੀਤਾ।", wordMeaning = "ਮੰਨ ਮੇਰਿਆ = ਹੇ ਮੇਰੇ ਮਨ! {ਲਫ਼ਜ਼ 'ਮੰਨ' ਦੀ (ੰ) ਇਕ ਮਾਤ੍ਰਾ ਵਧਾਣ ਵਾਸਤੇ ਹੀ ਹੈ, ਅਸਲ ਲਫ਼ਜ਼ 'ਮਨ' ਹੀ ਹੈ}।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-51", gurmukhi = "ਏਹ ਮਾਇਆ ਮੋਹਣੀ; ਜਿਨਿ ਏਤੁ ਭਰਮਿ ਭੁਲਾਇਆ ॥", transliteration = "eh maaiaa mohnee; jin et bharam bhulaaiaa ||", translation = "This Maya is so fascinating; because of it, people wander in doubt.", hindi = "एह माइआ मोहणी; जिनि एतु भरमि भुलाइआ ॥", punjabi = "(ਅੰਦਰੋਂ ਮੋਹਣੀ ਮਾਇਆ ਵਿਚ ਭੀ ਫਸਿਆ ਰਹੇ, ਤੇ, ਬਾਹਰੋਂ ਨਿਰੀਆਂ ਗੱਲਾਂ ਨਾਲ ਆਤਮਕ ਆਨੰਦ ਚਾਹੇ, ਇਹ ਨਹੀਂ ਹੋ ਸਕਦਾ)। ਇਹ ਮਾਇਆ ਜੀਵਾਂ ਨੂੰ ਆਪਣੇ ਮੋਹ ਵਿਚ ਫਸਾਣ ਲਈ ਬੜੀ ਡਾਢੀ ਹੈ, ਇਸ ਨੇ ਇਸ ਭੁਲੇਖੇ ਵਿਚ ਪਾਇਆ ਹੋਇਆ ਹੈ ਕਿ ਮੋਹ ਮਿੱਠੀ ਚੀਜ਼ ਹੈ, ਇਸ ਤਰ੍ਹਾਂ ਕੁਰਾਹੇ ਪਾਈ ਰੱਖਦੀ ਹੈ।", wordMeaning = "ਜਿਨਿ = ਜਿਸ (ਮਾਇਆ) ਨੇ। ਏਤੁ ਭਰਮਿ = ਇਸ ਭੁਲੇਖੇ ਵਿਚ ਕਿ ਮੋਹ ਇਕ ਮਿੱਠੀ ਚੀਜ਼ ਹੈ। ਭੁਲਾਇਆ = ਕੁਰਾਹੇ ਪਾ ਦਿੱਤਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-52", gurmukhi = "ਮਾਇਆ ਤ ਮੋਹਣੀ ਤਿਨੈ ਕੀਤੀ; ਜਿਨਿ ਠਗਉਲੀ ਪਾਈਆ ॥", transliteration = "maaiaa ta mohnee tinai keetee; jin thagaulee paaeeaa ||", translation = "This fascinating Maya was created by the One who has administered this potion.", hindi = "माइआ त मोहणी तिनै कीती; जिनि ठगउली पाईआ ॥", punjabi = "(ਪਰ ਜੀਵ ਦੇ ਭੀ ਕੀਹ ਵੱਸ?) ਜਿਸ ਪ੍ਰਭੂ ਨੇ ਮਾਇਆ ਦੇ ਮੋਹ ਦੀ ਠਗਬੂਟੀ (ਜੀਵਾਂ ਨੂੰ) ਚੰਬੋੜੀ ਹੈ ਉਸੇ ਨੇ ਇਹ ਮੋਹਣੀ ਮਾਇਆ ਪੈਦਾ ਕੀਤੀ ਹੈ।", wordMeaning = "ਤਿਨੈ = ਉਸੇ (ਪ੍ਰਭੂ) ਨੇ। ਜਿਨਿ = ਜਿਸ (ਪ੍ਰਭੂ) ਨੇ। ਠਗਉਲੀ = ਠਗ-ਬੂਟੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-53", gurmukhi = "ਕੁਰਬਾਣੁ ਕੀਤਾ ਤਿਸੈ ਵਿਟਹੁ; ਜਿਨਿ ਮੋਹੁ ਮੀਠਾ ਲਾਇਆ ॥", transliteration = "kurbaan keetaa tisai vitah; jin moh meethaa laaiaa ||", translation = "I am a sacrifice to the One who has made emotional attachment sweet.", hindi = "कुरबाणु कीता तिसै विटहु; जिनि मोहु मीठा लाइआ ॥", punjabi = "(ਸੋ, ਹੇ ਮੇਰੇ ਮਨ! ਆਪਣੇ ਆਪ ਨੂੰ ਮਾਇਆ ਤੋਂ ਸਦਕੇ ਕਰਨ ਦੇ ਥਾਂ) ਉਸ ਪ੍ਰਭੂ ਤੋਂ ਹੀ ਸਦਕੇ ਕਰੋ ਜਿਸ ਨੇ ਮਿੱਠਾ ਮੋਹ ਲਾਇਆ ਹੈ (ਤਦੋਂ ਹੀ ਇਹ ਮਿੱਠਾ ਮੋਹ ਮੁੱਕਦਾ ਹੈ)।", wordMeaning = "ਕੁਰਬਾਣੁ = ਸਦਕੇ, ਵਾਰਨੇ। ਵਿਟਹੁ = ਤੋਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-54", gurmukhi = "ਕਹੈ ਨਾਨਕੁ. ਮਨ ਚੰਚਲ; ਚਤੁਰਾਈ ਕਿਨੈ. ਨ ਪਾਇਆ ॥੧੦॥", transliteration = "kahai naanak. man chanchal; chturaaee kinai. na paaiaa ||10||", translation = "Says Nanak, O fickle mind, no one has found Him through cleverness. ||10||", hindi = "कहै नानकु. मन चंचल; चतुराई किनै. न पाइआ ॥१०॥", punjabi = "ਨਾਨਕ ਆਖਦਾ ਹੈ ਕਿ ਹੇ (ਮੇਰੇ) ਚੰਚਲ ਮਨ! ਚਤੁਰਾਈਆਂ ਨਾਲ ਕਿਸੇ ਨੇ (ਪਰਮਾਤਮਾ ਦੇ ਮਿਲਾਪ ਦਾ ਆਤਮਕ ਆਨੰਦ) ਨਹੀਂ ਲੱਭਾ ॥੧੦॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-55", gurmukhi = "ਏ ਮਨ ਪਿਆਰਿਆ; ਤੂ ਸਦਾ ਸਚੁ ਸਮਾਲੇ ॥", transliteration = "e man piaariaa; too sdaa sach smaale ||", translation = "O beloved mind, contemplate the True Lord forever.", hindi = "ए मन पिआरिआ; तू सदा सचु समाले ॥", punjabi = "ਹੇ ਪਿਆਰੇ ਮਨ! (ਜੇ ਤੂੰ ਸਦਾ ਦਾ ਆਤਮਕ ਆਨੰਦ ਲੋੜਦਾ ਹੈਂ ਤਾਂ) ਸਦਾ ਸੱਚੇ ਪ੍ਰਭੂ ਨੂੰ (ਆਪਣੇ ਅੰਦਰ) ਸੰਭਾਲ ਰੱਖ!", wordMeaning = "ਸਮਾਲੇ = ਸਮਾਲਿ, ਚੇਤੇ ਰੱਖ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-56", gurmukhi = "ਏਹੁ ਕੁਟੰਬੁ. ਤੂ ਜਿ ਦੇਖਦਾ; ਚਲੈ ਨਾਹੀ. ਤੇਰੈ ਨਾਲੇ ॥", transliteration = "eh kutamb. too ji dekhdaa; chlai naahee. terai naale ||", translation = "This family which you see shall not go along with you.", hindi = "एहु कुटंबु. तू जि देखदा; चलै नाही. तेरै नाले ॥", punjabi = "ਇਹ ਜੇਹੜਾ ਪਰਵਾਰ ਤੂੰ ਵੇਖਦਾ ਹੈਂ, ਇਸ ਨੇ ਤੇਰੇ ਨਾਲ ਨਹੀਂ ਨਿਭਣਾ।", wordMeaning = "ਜਿ = ਜੇਹੜਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-57", gurmukhi = "ਸਾਥਿ ਤੇਰੈ. ਚਲੈ ਨਾਹੀ; ਤਿਸੁ ਨਾਲਿ. ਕਿਉ ਚਿਤੁ ਲਾਈਐ ॥", transliteration = "saath terai. chlai naahee; tis naal. kiu chit laaeeai ||", translation = "They shall not go along with you, so why do you focus your attention on them?", hindi = "साथि तेरै. चलै नाही; तिसु नालि. किउ चितु लाईऐ ॥", punjabi = "ਇਸ ਪਰਵਾਰ ਦੇ ਮੋਹ ਵਿਚ ਕਿਉਂ ਫਸਦਾ ਹੈਂ? ਇਸ ਨੇ ਤੇਰੇ ਨਾਲ ਤੋੜ ਸਦਾ ਦਾ ਸਾਥ ਨਹੀਂ ਨਿਬਾਹ ਸਕਣਾ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-58", gurmukhi = "ਐਸਾ ਕੰਮੁ ਮੂਲੇ. ਨ ਕੀਚੈ; ਜਿਤੁ ਅੰਤਿ ਪਛੋਤਾਈਐ ॥", transliteration = "aisaa kamm moole. na keechai; jit ant pchhotaaeeai ||", translation = "Don't do anything that you will regret in the end.", hindi = "ऐसा कंमु मूले. न कीचै; जितु अंति पछोताईऐ ॥", punjabi = "ਜਿਸ ਕੰਮ ਦੇ ਕੀਤਿਆਂ ਆਖ਼ਰ ਹੱਥ ਮਲਣੇ ਪੈਣ, ਉਹ ਕੰਮ ਕਦੇ ਭੀ ਕਰਨਾ ਨਹੀਂ ਚਾਹੀਦਾ।", wordMeaning = "ਮੂਲੇ ਨ = ਬਿਲਕੁਲ ਨਹੀਂ। ਕੀਚੈ = ਕਰਨਾ ਚਾਹੀਦਾ। ਜਿਤੁ = ਜਿਸ ਕਰਕੇ। ਅੰਤਿ = ਅੰਤ ਵੇਲੇ, ਆਖ਼ਰ ਨੂੰ", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-59", gurmukhi = "ਸਤਿਗੁਰੂ ਕਾ ਉਪਦੇਸੁ ਸੁਣਿ ਤੂ; ਹੋਵੈ ਤੇਰੈ ਨਾਲੇ ॥", transliteration = "satiguroo kaa updes sun too; hovai terai naale ||", translation = "Listen to the Teachings of the True Guru - these shall go along with you.", hindi = "सतिगुरू का उपदेसु सुणि तू; होवै तेरै नाले ॥", punjabi = "ਸਤਿਗੁਰੂ ਦੀ ਸਿੱਖਿਆ (ਗਹੁ ਨਾਲ) ਸੁਣ, ਇਹ ਗੁਰ-ਉਪਦੇਸ਼ ਸਦਾ ਚੇਤੇ ਰੱਖਣਾ ਚਾਹੀਦਾ ਹੈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-60", gurmukhi = "ਕਹੈ ਨਾਨਕੁ. ਮਨ ਪਿਆਰੇ; ਤੂ ਸਦਾ ਸਚੁ ਸਮਾਲੇ ॥੧੧॥", transliteration = "kahai naanak. man piaare; too sdaa sach smaale ||11||", translation = "Says Nanak, O beloved mind, contemplate the True Lord forever. ||11||", hindi = "कहै नानकु. मन पिआरे; तू सदा सचु समाले ॥११॥", punjabi = "ਨਾਨਕ ਆਖਦਾ ਹੈ ਕਿ ਹੇ ਪਿਆਰੇ ਮਨ! (ਜੇ ਤੂੰ ਆਨੰਦ ਲੋੜਦਾ ਹੈਂ ਤਾਂ) ਸਦਾ-ਥਿਰ ਪਰਮਾਤਮਾ ਨੂੰ ਹਰ ਵੇਲੇ (ਆਪਣੇ ਅੰਦਰ) ਸਾਂਭ ਕੇ ਰੱਖ ॥੧੧॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-61", gurmukhi = "ਅਗਮ ਅਗੋਚਰਾ; ਤੇਰਾ ਅੰਤੁ. ਨ ਪਾਇਆ ॥", transliteration = "agam agochraa; teraa ant. na paaiaa ||", translation = "O inaccessible and unfathomable Lord, Your limits cannot be found.", hindi = "अगम अगोचरा; तेरा अंतु. न पाइआ ॥", punjabi = "(ਹੇ ਪਿਆਰੇ ਮਨ! ਸਦਾ ਪ੍ਰਭੂ ਨੂੰ ਆਪਣੇ ਅੰਦਰ ਸੰਭਾਲ ਰੱਖ, ਤੇ ਉਸ ਦੇ ਅੱਗੇ ਇਉਂ ਅਰਜ਼ੋਈ ਕਰ-) ਹੇ ਅਪਹੁੰਚ ਹਰੀ! ਹੇ ਇੰਦ੍ਰਿਆਂ ਦੀ ਪਹੁੰਚ ਤੋਂ ਪਰੇ ਰਹਿਣ ਵਾਲੇ ਪ੍ਰਭੂ! (ਤੇਰੇ ਗੁਣਾਂ ਦਾ) ਕਿਸੇ ਨੇ ਅੰਤ ਨਹੀਂ ਲੱਭਾ।", wordMeaning = "ਅਗਮ = ਹੇ ਅਪਹੁੰਚ ਪ੍ਰਭੂ! ਅਗੋਚਰਾ = ਹੇ ਅਗੋਚਰ ਹਰੀ! ਅਗੋਚਰ = ਅ-ਗੋ-ਚਰ, ਜਿਸ ਤਕ ਗਿਆਨ ਇੰਦ੍ਰਿਆਂ ਦੀ ਪਹੁੰਚ ਨ ਹੋ ਸਕੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-62", gurmukhi = "ਅੰਤੋ. ਨ ਪਾਇਆ ਕਿਨੈ ਤੇਰਾ; ਆਪਣਾ ਆਪੁ ਤੂ ਜਾਣਹੇ ॥", transliteration = "anto. na paaiaa kinai teraa; aapnaa aap too jaanhe ||", translation = "No one has found Your limits; only You Yourself know.", hindi = "अंतो. न पाइआ किनै तेरा; आपणा आपु तू जाणहे ॥", punjabi = "ਆਪਣੇ (ਅਸਲ) ਸਰੂਪ ਨੂੰ ਤੂੰ ਆਪ ਹੀ ਜਾਣਦਾ ਹੈਂ, ਹੋਰ ਕੋਈ ਜੀਵ ਤੇਰੇ ਗੁਣਾਂ ਦਾ ਅਖ਼ੀਰ ਨਹੀਂ ਲੱਭ ਸਕਦਾ।", wordMeaning = "ਕਿਨੈ = ਕਿਸੇ ਨੇ ਭੀ। ਆਪੁ = ਆਪਣੇ ਸਰੂਪ ਨੂੰ। ਜਾਣਹੇ = ਜਾਣਹਿ, ਤੂੰ ਜਾਣਦਾ ਹੈਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-63", gurmukhi = "ਜੀਅ ਜੰਤ ਸਭਿ ਖੇਲੁ ਤੇਰਾ; ਕਿਆ ਕੋ ਆਖਿ ਵਖਾਣਏ ॥", transliteration = "jeea jant sabh khel teraa; kiaa ko aakh vkhaanae ||", translation = "All living beings and creatures are Your play; how can anyone describe You?", hindi = "जीअ जंत सभि खेलु तेरा; किआ को आखि वखाणए ॥", punjabi = "ਕੋਈ ਹੋਰ ਜੀਵ (ਤੇਰੇ ਗੁਣਾਂ ਨੂੰ) ਆਖ ਕੇ ਬਿਆਨ ਕਰੇ ਭੀ ਕਿਸ ਤਰ੍ਹਾਂ? ਇਹ ਸਾਰੇ ਜੀਵ (ਤਾਂ) ਤੇਰਾ ਹੀ ਰਚਿਆ ਹੋਇਆ ਇਕ ਖੇਲ ਹੈ।", wordMeaning = "ਸਭਿ = ਸਾਰੇ। ਆਖਿ = ਆਖ ਕੇ। ਵਖਾਣਏ = ਵਖਾਣੈ, ਬਿਆਨ ਕਰੇ। ਕੋ = ਕੋਈ ਜੀਵ!", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-64", gurmukhi = "ਆਖਹਿ ਤ ਵੇਖਹਿ ਸਭੁ ਤੂਹੈ; ਜਿਨਿ ਜਗਤੁ ਉਪਾਇਆ ॥", transliteration = "aakhah ta vekhah sabh toohai; jin jagat upaaiaa ||", translation = "You speak, and You gaze upon all; You created the Universe.", hindi = "आखहि त वेखहि सभु तूहै; जिनि जगतु उपाइआ ॥", punjabi = "ਹਰੇਕ ਜੀਵ ਵਿਚ ਤੂੰ ਆਪ ਹੀ ਬੋਲਦਾ ਹੈਂ, ਹਰੇਕ ਜੀਵ ਦੀ ਤੂੰ ਆਪ ਹੀ ਸੰਭਾਲ ਕਰਦਾ ਹੈਂ (ਤੂੰ ਹੀ ਕਰਦਾ ਹੈਂ) ਜਿਸ ਨੇ ਇਹ ਸੰਸਾਰ ਪੈਦਾ ਕੀਤਾ ਹੈ।", wordMeaning = "ਆਖਹਿ = ਤੂੰ ਆਖਦਾ ਹੈਂ, ਤੂੰ ਬੋਲਦਾ ਹੈਂ। ਵੇਖਹਿ = ਤੂੰ ਸੰਭਾਲ ਕਰਦਾ ਹੈਂ। ਜਿਨਿ = ਜਿਸ ਤੈਂ ਨੇ।", startsAtMs = 0L, endsAtMs = 0L)
)

