    BaniLine(id = "anand-sahib-70", gurmukhi = "ਕਹੈ ਨਾਨਕੁ. ਜਿਸ ਨੋ ਆਪਿ ਤੁਠਾ; ਤਿਨਿ. ਅੰਮ੍ਰਿਤੁ ਗੁਰ ਤੇ ਪਾਇਆ ॥੧੩॥", transliteration = "kahai naanak. jis no aap tuthaa; tin. amrit gur te paaiaa ||13||", translation = "Says Nanak, those with whom the Lord is pleased, obtain the Amrit, through the Guru. ||13||", hindi = "कहै नानकु. जिस नो आपि तुठा; तिनि. अंम्रितु गुर ते पाइआ ॥१३॥", punjabi = "ਨਾਨਕ ਆਖਦਾ ਹੈ ਕਿ ਪ੍ਰਭੂ ਜਿਸ ਮਨੁੱਖ ਉਤੇ ਪ੍ਰਸੰਨ ਹੁੰਦਾ ਹੈ, ਉਸ ਮਨੁੱਖ ਨੇ (ਆਤਮਕ ਆਨੰਦ-ਰੂਪ) ਅੰਮ੍ਰਿਤ ਗੁਰੂ ਤੋਂ ਪ੍ਰਾਪਤ ਕਰ ਲਿਆ ਹੈ ॥੧੩॥", wordMeaning = "ਤੇ = ਤੋਂ ॥੧੩॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-71", gurmukhi = "ਭਗਤਾ ਕੀ; ਚਾਲ ਨਿਰਾਲੀ ॥", transliteration = "bhagtaa kee; chaal niraalee ||", translation = "The lifestyle of the devotees is unique and distinct.", hindi = "भगता की; चाल निराली ॥", punjabi = "(ਜੇਹੜੇ ਸੁਭਾਗ ਬੰਦੇ ਆਤਮਕ ਆਨੰਦ ਮਾਣਦੇ ਹਨ ਉਹੀ ਭਗਤ ਹਨ ਤੇ ਉਹਨਾਂ) ਭਗਤਾਂ ਦੀ ਜੀਵਨ-ਜੁਗਤੀ (ਦੁਨੀਆ ਦੇ ਲੋਕਾਂ ਨਾਲੋਂ ਸਦਾ) ਵੱਖਰੀ ਹੁੰਦੀ ਹੈ,", wordMeaning = "ਭਗਤ = ਆਤਮਕ ਆਨੰਦ ਮਾਣਨ ਵਾਲੇ ਬੰਦੇ। ਚਾਲ = ਜੀਵਨ ਜੁਗਤੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-72", gurmukhi = "ਚਾਲਾ ਨਿਰਾਲੀ ਭਗਤਾਹ ਕੇਰੀ; ਬਿਖਮ ਮਾਰਗਿ ਚਲਣਾ ॥", transliteration = "chaalaa niraalee bhagtaah keree; bikham maarag chalnaa ||", translation = "The devotees' lifestyle is unique and distinct; they follow the most difficult path.", hindi = "चाला निराली भगताह केरी; बिखम मारगि चलणा ॥", punjabi = "(ਇਹ ਪੱਕੀ ਗੱਲ ਹੈ ਕਿ ਉਹਨਾਂ) ਭਗਤਾਂ ਦੀ ਜੀਵਨ-ਜੁਗਤੀ (ਹੋਰਨਾਂ ਨਾਲੋਂ) ਵੱਖਰੀ ਹੁੰਦੀ ਹੈ। ਉਹ (ਬੜੇ) ਔਖੇ ਰਸਤੇ ਉਤੇ ਤੁਰਦੇ ਹਨ।", wordMeaning = "ਨਿਰਾਲੀ = ਵੱਖਰੀ। ਕੇਰੀ = ਦੀ। ਬਿਖਮ = ਔਖਾ। ਮਾਰਗਿ = ਰਾਹ ਉਤੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-73", gurmukhi = "ਲਬੁ ਲੋਭੁ ਅਹੰਕਾਰੁ ਤਜਿ ਤ੍ਰਿਸਨਾ; ਬਹੁਤੁ. ਨਾਹੀ ਬੋਲਣਾ ॥", transliteration = "lab lobh ahankaar taj trisnaa; bhut. naahee bolnaa ||", translation = "They renounce greed, avarice, egotism and desire; they do not talk too much.", hindi = "लबु लोभु अहंकारु तजि त्रिसना; बहुतु. नाही बोलणा ॥", punjabi = "ਉਹ ਲੱਬ ਲੋਭ ਅਹੰਕਾਰ ਤੇ ਮਾਇਆ ਦੀ ਤ੍ਰਿਸ਼ਨਾ ਤਿਆਗਦੇ ਹਨ ਤੇ ਬਹੁਤਾ ਨਹੀਂ ਬੋਲਦੇ (ਭਾਵ, ਆਪਣੀ ਸੋਭਾ ਨਹੀਂ ਕਰਦੇ ਫਿਰਦੇ)।", wordMeaning = "ਤਜਿ = ਤਿਆਗ ਕੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-74", gurmukhi = "ਖੰਨਿਅਹੁ ਤਿਖੀ. ਵਾਲਹੁ ਨਿਕੀ; ਏਤੁ ਮਾਰਗਿ ਜਾਣਾ ॥", transliteration = "khanniah tikhee. vaalah nikee; et maarag jaanaa ||", translation = "The path they take is sharper than a two-edged sword, and finer than a hair.", hindi = "खंनिअहु तिखी. वालहु निकी; एतु मारगि जाणा ॥", punjabi = "ਇਸ ਰਸਤੇ ਉਤੇ ਤੁਰਨਾ (ਬੜੀ ਔਖੀ ਖੇਡ ਹੈ ਕਿਉਂਕਿ ਇਹ ਰਸਤਾ) ਖੰਡੇ ਦੀ ਧਾਰ ਨਾਲੋਂ ਤ੍ਰਿੱਖਾ ਹੈ ਤੇ ਵਾਲ ਨਾਲੋਂ ਪਤਲਾ ਹੈ (ਇਸ ਉਤੋਂ ਡਿੱਗਣ ਦੀ ਭੀ ਸੰਭਾਵਨਾ ਹਰ ਵੇਲੇ ਬਣੀ ਰਹਿੰਦੀ ਹੈ ਕਿਉਂਕਿ ਦੁਨੀਆ ਵਾਲੀ ਵਾਸਨਾ ਮਨ ਦੀ ਅਡੋਲਤਾ ਨੂੰ ਧੱਕਾ ਦੇ ਦੇਂਦੀ ਹੈ)।", wordMeaning = "ਖੰਨਿਅਹੁ = ਖੰਡੇ ਨਾਲੋਂ, ਤਲਵਾਰ ਨਾਲੋਂ। ਵਾਲਹੁ = ਵਾਲ ਨਾਲੋਂ। ਨਿਕੀ = ਬਾਰੀਕ। ਏਤੁ ਮਾਰਗਿ = ਇਸ ਰਸਤੇ ਉਤੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-75", gurmukhi = "ਗੁਰ ਪਰਸਾਦੀ ਜਿਨੀ ਆਪੁ ਤਜਿਆ; ਹਰਿ ਵਾਸਨਾ ਸਮਾਣੀ ॥", transliteration = "gur parsaadee jinee aap tjiaa; har vaasnaa smaanee ||", translation = "By Guru's Grace, they shed their selfishness and conceit; their hopes are merged in the Lord.", hindi = "गुर परसादी जिनी आपु तजिआ; हरि वासना समाणी ॥", punjabi = "ਪਰ ਜਿਨ੍ਹਾਂ ਨੇ ਗੁਰੂ ਦੀ ਕਿਰਪਾ ਨਾਲ ਆਪਾ-ਭਾਵ ਛੱਡ ਦਿੱਤਾ ਹੈ, ਉਹਨਾਂ ਦੀ (ਮਾਇਕ) ਵਾਸਨਾ ਹਰੀ-ਪ੍ਰਭੂ ਦੀ ਯਾਦ ਵਿਚ ਮੁੱਕ ਜਾਂਦੀ ਹੈ।", wordMeaning = "ਆਪੁ = ਆਪਾ-ਭਾਵ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-76", gurmukhi = "ਕਹੈ ਨਾਨਕੁ. ਚਾਲ ਭਗਤਾ; ਜੁਗਹੁ ਜੁਗੁ ਨਿਰਾਲੀ ॥੧੪॥", transliteration = "kahai naanak. chaal bhagtaa; jugah jug niraalee ||14||", translation = "Says Nanak, the lifestyle of the devotees, in each and every age, is unique and distinct. ||14||", hindi = "कहै नानकु. चाल भगता; जुगहु जुगु निराली ॥१४॥", punjabi = "ਨਾਨਕ ਆਖਦਾ ਹੈ ਕਿ (ਆਤਮਕ ਆਨੰਦ ਮਾਣਨ ਵਾਲੇ) ਭਗਤ ਜਨਾਂ ਦੀ ਜੀਵਨ-ਜੁਗਤੀ ਸਦਾ ਤੋਂ ਹੀ (ਦੁਨੀਆ ਨਾਲੋਂ) ਵੱਖਰੀ ਚਲੀ ਆ ਰਹੀ ਹੈ ॥੧੪॥", wordMeaning = "ਜੁਗਹੁ ਜੁਗੁ = ਹਰੇਕ ਜੁਗ ਵਿਚ, ਸਦਾ ਹੀ, ਹਰ ਸਮੇ ॥੧੪॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-77", gurmukhi = "ਜਿਉ ਤੂ ਚਲਾਇਹਿ. ਤਿਵ ਚਲਹ ਸੁਆਮੀ; ਹੋਰੁ. ਕਿਆ ਜਾਣਾ ਗੁਣ ਤੇਰੇ ॥", transliteration = "jiu too chlaaih. tiv chalah suaamee; hor. kiaa jaanaa gun tere ||", translation = "As You make me walk, so do I walk, O my Lord and Master; what else do I know of Your Glorious Virtues?", hindi = "जिउ तू चलाइहि. तिव चलह सुआमी; होरु. किआ जाणा गुण तेरे ॥", punjabi = "ਹੇ ਮਾਲਕ-ਪ੍ਰਭੂ! ਜਿਵੇਂ ਤੂੰ (ਸਾਨੂੰ ਜੀਵਾਂ ਨੂੰ ਜੀਵਨ-ਸੜਕ ਉਤੇ) ਤੋਰਦਾ ਹੈਂ, ਤਿਵੇਂ ਅਸੀਂ ਤੁਰਦੇ ਹਾਂ (ਬੱਸ! ਮੈਨੂੰ ਇਤਨੀ ਹੀ ਸੂਝ ਪਈ ਹੈ), ਤੇਰੇ ਗੁਣਾਂ ਦਾ ਹੋਰ ਭੇਤ ਮੈਂ ਨਹੀਂ ਜਾਣਦਾ।", wordMeaning = "ਚਲਹ = ਅਸੀਂ ਜੀਵ ਤੁਰਦੇ ਹਾਂ। ਹੋਰੁ = ਹੋਰ ਭੇਤ। ਕਿਆ ਜਾਣਾ = ਮੈਂ ਨਹੀਂ ਜਾਣਦਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-78", gurmukhi = "ਜਿਵ ਤੂ ਚਲਾਇਹਿ. ਤਿਵੈ ਚਲਹ; ਜਿਨਾ ਮਾਰਗਿ ਪਾਵਹੇ ॥", transliteration = "jiv too chlaaih. tivai chalah; jinaa maarag paavhe ||", translation = "As You cause them to walk, they walk - You have placed them on the Path.", hindi = "जिव तू चलाइहि. तिवै चलह; जिना मारगि पावहे ॥", punjabi = "(ਮੈਂ ਇਹੀ ਸਮਝਿਆ ਹਾਂ ਕਿ) ਜਿਸ ਰਾਹੇ ਤੂੰ ਸਾਨੂੰ ਤੋਰਦਾ ਹੈਂ, ਉਸੇ ਰਾਹੇ ਅਸੀਂ ਤੁਰਦੇ ਹਾਂ। ਜਿਨ੍ਹਾਂ ਬੰਦਿਆਂ ਨੂੰ (ਆਤਮਕ ਆਨੰਦ ਮਾਣਨ ਦੇ) ਰਸਤੇ ਉਤੇ ਤੋਰਦਾ ਹੈਂ,", wordMeaning = "ਮਾਰਗਿ = (ਆਨੰਦ ਦੇ) ਰਸਤੇ ਉਤੇ। ਪਾਵਹੇ = ਪਾਵਹਿ, ਤੂੰ ਪਾਂਦਾ ਹੈਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-79", gurmukhi = "ਕਰਿ ਕਿਰਪਾ. ਜਿਨ ਨਾਮਿ ਲਾਇਹਿ; ਸਿ ਹਰਿ ਹਰਿ ਸਦਾ ਧਿਆਵਹੇ ॥", transliteration = "kar kirpaa. jin naam laaih; si har har sdaa dhiaavhe ||", translation = "In Your Mercy, You attach them to the Naam; they meditate forever on the Lord, Har, Har.", hindi = "करि किरपा. जिन नामि लाइहि; सि हरि हरि सदा धिआवहे ॥", punjabi = "ਜਿਨ੍ਹਾਂ ਨੂੰ ਮੇਹਰ ਕਰ ਕੇ ਆਪਣੇ ਨਾਮ ਵਿਚ ਜੋੜਦਾ ਹੈਂ, ਉਹ ਬੰਦੇ ਸਦਾ ਹਰੀ-ਨਾਮ ਸਿਮਰਦੇ ਹਨ।", wordMeaning = "ਲਾਇਹਿ = ਤੂੰ ਲਾਂਦਾ ਹੈਂ। ਸਿ = ਉਹ ਬੰਦੇ। ਧਿਆਵੇ = ਧਿਆਵਹਿ, ਧਿਆਉਂਦੇ ਹਨ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-80", gurmukhi = "ਜਿਸ ਨੋ ਕਥਾ ਸੁਣਾਇਹਿ ਆਪਣੀ; ਸਿ ਗੁਰਦੁਆਰੈ ਸੁਖੁ ਪਾਵਹੇ ॥", transliteration = "jis no kthaa sunaaih aapnee; si gurduaarai sukh paavhe ||", translation = "Those whom You cause to listen to Your sermon, find peace in the Gurdwara, the Guru's Gate.", hindi = "जिस नो कथा सुणाइहि आपणी; सि गुरदुआरै सुखु पावहे ॥", punjabi = "ਜਿਸ ਜਿਸ ਮਨੁੱਖ ਨੂੰ ਤੂੰ ਆਪਣੀ ਸਿਫ਼ਤ-ਸਾਲਾਹ ਦੀ ਬਾਣੀ ਸੁਣਾਉਂਦਾ ਹੈਂ (ਸੁਣਨ ਵਲ ਪ੍ਰੇਰਦਾ ਹੈਂ), ਉਹ ਬੰਦੇ ਗੁਰੂ ਦੇ ਦਰ ਤੇ (ਪਹੁੰਚ ਕੇ) ਆਤਮਕ ਆਨੰਦ ਮਾਣਦੇ ਹਨ।", wordMeaning = "ਸੁਖੁ = ਆਤਮਕ ਆਨੰਦ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-81", gurmukhi = "ਕਹੈ ਨਾਨਕੁ. ਸਚੇ ਸਾਹਿਬ; ਜਿਉ ਭਾਵੈ ਤਿਵੈ ਚਲਾਵਹੇ ॥੧੫॥", transliteration = "kahai naanak. sche saahib; jiu bhaavai tivai chlaavhe ||15||", translation = "Says Nanak, O my True Lord and Master, you make us walk according to Your Will. ||15||", hindi = "कहै नानकु. सचे साहिब; जिउ भावै तिवै चलावहे ॥१५॥", punjabi = "ਨਾਨਕ ਆਖਦਾ ਹੈ ਕਿ ਹੇ ਸਦਾ-ਥਿਰ ਰਹਿਣ ਵਾਲੇ ਮਾਲਕ! ਜਿਵੇਂ ਤੈਨੂੰ ਚੰਗਾ ਲੱਗਦਾ ਹੈ, ਉਸੇ ਤਰ੍ਹਾਂ ਤੂੰ (ਸਾਨੂੰ ਜੀਵਾਂ ਨੂੰ) ਜੀਵਨ-ਰਾਹ ਉਤੇ ਤੋਰਦਾ ਹੈਂ ॥੧੫॥", wordMeaning = "ਤਿਵੈ = ਉਸੇ ਤਰ੍ਹਾਂ, ਤਿਉਂ ਹੀ ॥੧੫॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-82", gurmukhi = "ਏਹੁ ਸੋਹਿਲਾ; ਸਬਦੁ ਸੁਹਾਵਾ ॥", transliteration = "eh sohilaa; sabad suhaavaa ||", translation = "This song of praise is the Shabad, the most beautiful Word of God.", hindi = "एहु सोहिला; सबदु सुहावा ॥", punjabi = "(ਸਤਿਗੁਰੂ ਦਾ) ਇਹ ਸੋਹਣਾ ਸ਼ਬਦ (ਆਤਮਕ) ਆਨੰਦ ਦੇਣ ਵਾਲਾ ਗੀਤ ਹੈ,", wordMeaning = "ਸੋਹਿਲਾ = ਖ਼ੁਸ਼ੀ ਦਾ ਗੀਤ, ਆਨੰਦ ਦੇਣ ਵਾਲਾ ਗੀਤ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-83", gurmukhi = "ਸਬਦੋ ਸੁਹਾਵਾ ਸਦਾ ਸੋਹਿਲਾ; ਸਤਿਗੁਰੂ ਸੁਣਾਇਆ ॥", transliteration = "sabdo suhaavaa sdaa sohilaa; stiguroo sunaaiaa ||", translation = "This beauteous Shabad is the everlasting song of praise, spoken by the True Guru.", hindi = "सबदो सुहावा सदा सोहिला; सतिगुरू सुणाइआ ॥", punjabi = "(ਯਕੀਨ ਜਾਣੋ ਕਿ) ਸਤਿਗੁਰੂ ਨੇ ਜੇਹੜਾ ਸੋਹਣਾ ਸ਼ਬਦ ਸੁਣਾਇਆ ਹੈ ਉਹ ਸਦਾ ਆਤਮਕ ਆਨੰਦ ਦੇਣ ਵਾਲਾ ਹੈ।", wordMeaning = "ਸੁਹਾਵਾ = ਸੋਹਣਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-84", gurmukhi = "ਏਹੁ ਤਿਨ ਕੈ ਮੰਨਿ ਵਸਿਆ; ਜਿਨ ਧੁਰਹੁ ਲਿਖਿਆ ਆਇਆ ॥", transliteration = "eh tin kai mann vsiaa; jin dhurah likhiaa aaiaa ||", translation = "This is enshrined in the minds of those who are so pre-destined by the Lord.", hindi = "एहु तिन कै मंनि वसिआ; जिन धुरहु लिखिआ आइआ ॥", punjabi = "ਪਰ ਇਹ ਗੁਰ-ਸ਼ਬਦ ਉਹਨਾਂ ਦੇ ਮਨ ਵਿਚ ਵੱਸਦਾ ਹੈ ਜਿਨ੍ਹਾਂ ਦੇ ਮੱਥੇ ਤੇ ਧੁਰੋਂ ਲਿਖਿਆ ਲੇਖ ਉੱਘੜਦਾ ਹੈ।", wordMeaning = "ਏਹੁ = ਇਹ ਸੋਹਿਲਾ। ਮੰਨਿ = ਮਨ ਵਿਚ {ਅੱਖਰ 'ਮ' ਦੀ (ੰ) ਸਿਰਫ਼ ਇਕ ਮਾਤ੍ਰਾ ਵਧਾਣ ਵਾਸਤੇ ਹੈ, ਅਸਲ ਲਫ਼ਜ਼ 'ਮਨ' ਹੀ ਹੈ}।", startsAtMs = 0L, endsAtMs = 0L),
