    BaniLine(id = "anand-sahib-97", gurmukhi = "ਜੀਅਹੁ ਮੈਲੇ; ਬਾਹਰਹੁ ਨਿਰਮਲ ॥", transliteration = "jeeah maile; baaharah niramal ||", translation = "Inwardly polluted, and outwardly pure.", hindi = "जीअहु मैले; बाहरहु निरमल ॥", punjabi = "(ਨਿਰੇ ਬਾਹਰੋਂ ਧਾਰਮਿਕ ਦਿੱਸਦੇ ਕਰਮ ਕਰਨ ਵਾਲੇ ਬੰਦੇ) ਮਨ ਵਿਚ (ਵਿਕਾਰਾਂ ਨਾਲ) ਮੈਲੇ ਰਹਿੰਦੇ ਹਨ ਤੇ ਸਿਰਫ਼ ਵੇਖਣ ਨੂੰ ਹੀ ਪਵਿਤ੍ਰ ਜਾਪਦੇ ਹਨ।", wordMeaning = "ਜੀਅਹੁ = ਜਿੰਦ ਤੋਂ, ਮਨ ਵਿਚੋਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-98", gurmukhi = "ਬਾਹਰਹੁ ਨਿਰਮਲ. ਜੀਅਹੁ ਤ ਮੈਲੇ; ਤਿਨੀ ਜਨਮੁ ਜੂਐ ਹਾਰਿਆ ॥", transliteration = "baaharah niramal. jeeah ta maile; tinee janam jooai haariaa ||", translation = "Those who are outwardly pure and yet polluted within, lose their lives in the gamble.", hindi = "बाहरहु निरमल. जीअहु त मैले; तिनी जनमु जूऐ हारिआ ॥", punjabi = "ਤੇ, ਜੇਹੜੇ ਬੰਦੇ ਬਾਹਰੋਂ ਪਵਿਤ੍ਰ ਦਿੱਸਣ, ਉਂਞ ਮਨੋਂ ਵਿਕਾਰੀ ਹੋਣ, ਉਹਨਾਂ ਨੇ ਆਪਣਾ ਜੀਵਨ ਇਉਂ ਵਿਅਰਥ ਗਵਾ ਲਿਆ ਸਮਝੋ ਜਿਵੇਂ ਕੋਈ ਜੁਆਰੀਆ ਜੂਏ ਵਿਚ ਧਨ ਹਾਰ ਆਉਂਦਾ ਹੈ।", wordMeaning = "ਤਿਨੀ = ਉਹਨਾਂ ਬੰਦਿਆਂ ਨੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-99", gurmukhi = "ਏਹ ਤਿਸਨਾ ਵਡਾ ਰੋਗੁ ਲਗਾ; ਮਰਣੁ ਮਨਹੁ ਵਿਸਾਰਿਆ ॥", transliteration = "eh tisnaa vdaa rog lgaa; maran manah visaariaa ||", translation = "They contract this terrible disease of desire, and in their minds, they forget about dying.", hindi = "एह तिसना वडा रोगु लगा; मरणु मनहु विसारिआ ॥", punjabi = "(ਉਹਨਾਂ ਨੂੰ ਅੰਦਰੋ-ਅੰਦਰ) ਮਾਇਆ ਦੀ ਤ੍ਰਿਸ਼ਨਾ ਦਾ ਭਾਰਾ ਰੋਗ ਖਾਈ ਜਾਂਦਾ ਹੈ, (ਮਾਇਆ ਦੇ ਲਾਲਚ ਵਿਚ) ਮੌਤ ਨੂੰ ਉਹਨਾਂ ਭੁਲਾਇਆ ਹੁੰਦਾ ਹੈ।", wordMeaning = "ਮਰਣੁ = ਮੌਤ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-100", gurmukhi = "ਵੇਦਾ ਮਹਿ ਨਾਮੁ ਉਤਮੁ. ਸੋ ਸੁਣਹਿ ਨਾਹੀ; ਫਿਰਹਿ ਜਿਉ ਬੇਤਾਲਿਆ ॥", transliteration = "vedaa mah naam utam. so sunah naahee; phirah jiu betaaliaa ||", translation = "In the Vedas, the ultimate objective is the Naam, the Name of the Lord; but they do not hear this, and they wander around like demons.", hindi = "वेदा महि नामु उतमु. सो सुणहि नाही; फिरहि जिउ बेतालिआ ॥", punjabi = "(ਲੋਕਾਂ ਦੀਆਂ ਨਜ਼ਰਾਂ ਵਿਚ ਧਾਰਮਿਕ ਦਿੱਸਣ ਵਾਸਤੇ ਉਹ ਆਪਣੇ ਬਾਹਰੋਂ ਧਾਰਮਿਕ ਦਿੱਸਦੇ ਕਰਮਾਂ ਦੀ ਵਡਿਆਈ ਦੱਸਣ ਲਈ ਵੇਦ ਆਦਿਕ ਧਰਮ-ਪੁਸਤਕਾਂ ਵਿਚੋਂ ਹਵਾਲੇ ਦੇਂਦੇ ਹਨ, ਪਰ) ਵੇਦ ਆਦਿਕ ਧਰਮ-ਪੁਸਤਕਾਂ ਵਿਚ ਜੋ ਪ੍ਰਭੂ ਦਾ ਨਾਮ ਜਪਣ ਦਾ ਉੱਤਮ ਉਪਦੇਸ਼ ਹੈ ਉਸ ਵਲ ਉਹ ਧਿਆਨ ਨਹੀਂ ਕਰਦੇ, ਤੇ ਭੂਤਾਂ ਵਾਂਗ ਹੀ ਜਗਤ ਵਿਚ ਵਿਚਰਦੇ ਹਨ (ਜੀਵਨ-ਤਾਲ ਤੋਂ ਖੁੰਝੇ ਰਹਿੰਦੇ ਹਨ)।", wordMeaning = "ਬੇਤਾਲੇ = ਭੂਤਨੇ, ਤਾਲ ਤੋਂ, ਖੁੰਝੇ ਹੋਏ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-101", gurmukhi = "ਕਹੈ ਨਾਨਕੁ. ਜਿਨ ਸਚੁ ਤਜਿਆ. ਕੂੜੇ ਲਾਗੇ; ਤਿਨੀ ਜਨਮੁ ਜੂਐ ਹਾਰਿਆ ॥੧੯॥", transliteration = "kahai naanak. jin sach tjiaa. koore laage; tinee janam jooai haariaa ||19||", translation = "Says Nanak, those who forsake Truth and cling to falsehood, lose their lives in the gamble. ||19||", hindi = "कहै नानकु. जिन सचु तजिआ. कूड़े लागे; तिनी जनमु जूऐ हारिआ ॥१९॥", punjabi = "ਨਾਨਕ ਆਖਦਾ ਹੈ ਕਿ ਜਿਨ੍ਹਾਂ ਨੇ ਪਰਮਾਤਮਾ ਦਾ ਨਾਮ (-ਸਿਮਰਨ) ਛੱਡਿਆ ਹੋਇਆ ਹੈ, ਤੇ ਜੋ ਮਾਇਆ ਦੇ ਮੋਹ ਵਿਚ ਫਸੇ ਹੋਏ ਹਨ, ਉਹਨਾਂ ਆਪਣੀ ਜੀਵਨ-ਖੇਡ ਜੂਏ ਵਿਚ ਹਾਰ ਲਈ ਸਮਝੋ ॥੧੯॥", wordMeaning = "ਜਿਨ = ਜਿਨ੍ਹਾਂ ਨੇ ॥੧੯॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-102", gurmukhi = "ਜੀਅਹੁ ਨਿਰਮਲ; ਬਾਹਰਹੁ ਨਿਰਮਲ ॥", transliteration = "jeeah niramal; baaharah niramal ||", translation = "Inwardly pure, and outwardly pure.", hindi = "जीअहु निरमल; बाहरहु निरमल ॥", punjabi = "ਉਹ ਬੰਦੇ ਮਨੋਂ ਭੀ ਪਵਿਤ੍ਰ ਹੁੰਦੇ ਹਨ, ਤੇ ਬਾਹਰੋਂ ਭੀ ਪਵਿਤ੍ਰ ਹੁੰਦੇ ਹਨ,", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-103", gurmukhi = "ਬਾਹਰਹੁ ਤ ਨਿਰਮਲ. ਜੀਅਹੁ ਨਿਰਮਲ; ਸਤਿਗੁਰ ਤੇ. ਕਰਣੀ ਕਮਾਣੀ ॥", transliteration = "baaharah ta niramal. jeeah niramal; stigur te. karnee kmaanee ||", translation = "Those who are outwardly pure and also pure within, through the Guru, perform good deeds.", hindi = "बाहरहु त निरमल. जीअहु निरमल; सतिगुर ते. करणी कमाणी ॥", punjabi = "ਜੋ ਬੰਦੇ (ਆਚਰਨ-ਉਸਾਰੀ ਦੀ) ਉਹ ਕਮਾਈ ਕਰਦੇ ਹਨ ਜਿਸ ਦੀ ਹਿਦਾਇਤ ਗੁਰੂ ਤੋਂ ਮਿਲਦੀ ਹੈ, ਉਹ ਮਨੋਂ ਭੀ ਪਵਿਤ੍ਰ ਹੁੰਦੇ ਹਨ, ਤੇ ਬਾਹਰੋਂ ਭੀ ਪਵਿਤ੍ਰ ਹੁੰਦੇ ਹਨ (ਭਾਵ, ਉਹਨਾਂ ਦਾ ਜਗਤ ਨਾਲ ਵਰਤਾਰਾ ਭੀ ਸੁਚੱਜਾ ਹੁੰਦਾ ਹੈ), ਉਹ ਬਾਹਰੋਂ ਭੀ ਪਵਿਤ੍ਰ ਤੇ ਅੰਦਰੋਂ ਭੀ ਸੁੱਚੇ ਰਹਿੰਦੇ ਹਨ।", wordMeaning = "ਸਤਿਗੁਰ ਤੇ = ਗੁਰੂ ਤੋਂ (ਮਿਲੀ ਹੋਈ), ਜਿਸ ਦਾ ਉਪਦੇਸ਼ ਗੁਰੂ ਤੋਂ ਮਿਲਿਆ ਹੈ। ਕਰਣੀ = ਆਚਰਨ, ਕਰਨ-ਯੋਗ ਕੰਮ। ਕਮਾਣੀ = ਕਮਾਈ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-104", gurmukhi = "ਕੂੜ ਕੀ ਸੋਇ. ਪਹੁਚੈ ਨਾਹੀ; ਮਨਸਾ ਸਚਿ ਸਮਾਣੀ ॥", transliteration = "koor kee soi. phuchai naahee; mansaa sach smaanee ||", translation = "Not even an iota of falsehood touches them; their hopes are absorbed in the Truth.", hindi = "कूड़ की सोइ. पहुचै नाही; मनसा सचि समाणी ॥", punjabi = "ਉਹਨਾਂ ਦੇ ਮਨ ਦਾ ਮਾਇਕ ਫੁਰਨਾ ਸਿਮਰਨ ਵਿਚ ਹੀ ਮੁੱਕ ਜਾਂਦਾ ਹੈ, (ਉਹਨਾਂ ਦੇ ਅੰਦਰ ਇਤਨਾ ਆਤਮਕ ਆਨੰਦ ਬਣਦਾ ਹੈ ਕਿ) ਮਾਇਆ ਦੇ ਮੋਹ ਦੀ ਖ਼ਬਰ ਤਕ ਉਹਨਾਂ ਦੇ ਮਨ ਤਕ ਨਹੀਂ ਪਹੁੰਚਦੀ।", wordMeaning = "ਕੂੜ = ਮਾਇਆ ਦਾ ਮੋਹ। ਸੋਇ = ਖ਼ਬਰ। ਮਨਸਾ = ਮਨ ਦਾ ਫੁਰਨਾ, ਮਨ ਵਿਚ ਮਾਇਆ ਦੇ ਮੋਹ ਦਾ ਫੁਰਨਾ। ਸਚਿ = ਪ੍ਰਭੂ ਦੇ ਸਿਮਰਨ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-105", gurmukhi = "ਜਨਮੁ ਰਤਨੁ ਜਿਨੀ ਖਟਿਆ; ਭਲੇ ਸੇ ਵਣਜਾਰੇ ॥", transliteration = "janam ratan jinee khtiaa; bhle se vanjaare ||", translation = "Those who earn the jewel of this human life, are the most excellent of merchants.", hindi = "जनमु रतनु जिनी खटिआ; भले से वणजारे ॥", punjabi = "(ਜੀਵ ਜਗਤ ਵਿਚ ਆਤਮਕ ਆਨੰਦ ਦਾ ਵੱਖਰ ਵਿਹਾਝਣ ਆਏ ਹਨ) ਉਹੀ ਜੀਵ-ਵਪਾਰੀ ਚੰਗੇ ਕਹੇ ਜਾਂਦੇ ਹਨ ਜਿਨ੍ਹਾਂ ਨੇ (ਗੁਰੂ ਦੇ ਦੱਸੇ ਰਾਹ ਉਤੇ ਤੁਰ ਕੇ ਨਾਮ-ਕਮਾਈ ਕਰ ਕੇ) ਸ੍ਰੇਸ਼ਟ ਮਨੁੱਖਾ ਜਨਮ ਸਫਲਾ ਕਰ ਲਿਆ।", wordMeaning = "ਵਣਜਾਰੇ = (ਜਗਤ ਵਿਚ ਭਗਤੀ ਦਾ) ਵਜਣ ਕਰਨ ਆਏ ਬੰਦੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-106", gurmukhi = "ਕਹੈ ਨਾਨਕੁ. ਜਿਨ ਮੰਨੁ ਨਿਰਮਲੁ; ਸਦਾ ਰਹਹਿ ਗੁਰ ਨਾਲੇ ॥੨੦॥", transliteration = "kahai naanak. jin mann niramal; sdaa rahah gur naale ||20||", translation = "Says Nanak, those whose minds are pure, abide with the Guru forever. ||20||", hindi = "कहै नानकु. जिन मंनु निरमलु; सदा रहहि गुर नाले ॥२०॥", punjabi = "ਨਾਨਕ ਆਖਦਾ ਹੈ ਕਿ ਜਿਨ੍ਹਾਂ ਬੰਦਿਆਂ ਦਾ ਮਨ ਪਵਿਤ੍ਰ ਹੋ ਜਾਂਦਾ ਹੈ (ਜਿਨ੍ਹਾਂ ਦੇ ਅੰਦਰ ਆਤਮਕ ਆਨੰਦ ਬਣ ਜਾਂਦਾ ਹੈ) ਉਹ (ਅੰਤਰ ਆਤਮੇ) ਸਦਾ ਗੁਰੂ ਦੇ ਚਰਨਾਂ ਵਿਚ ਰਹਿੰਦੇ ਹਨ ॥੨੦॥", wordMeaning = "ਮੰਨੁ = ਮਨ ॥੨੦॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-107", gurmukhi = "ਜੇ ਕੋ ਸਿਖੁ; ਗੁਰੂ ਸੇਤੀ ਸਨਮੁਖੁ ਹੋਵੈ ॥", transliteration = "je ko sikh; guroo setee sanmukh hovai ||", translation = "If a Sikh turns to the Guru with sincere faith, as sunmukh", hindi = "जे को सिखु; गुरू सेती सनमुखु होवै ॥", punjabi = "ਜੇ ਕੋਈ ਸਿੱਖ ਗੁਰੂ ਦੇ ਸਾਹਮਣੇ ਸੁਰਖ਼ਰੂ ਹੋਣਾ ਚਾਹੁੰਦਾ ਹੈ,", wordMeaning = "ਸੇਤੀ = ਨਾਲ। ਸਨਮੁਖੁ = ਸਾਹਮਣੇ ਮੂੰਹ ਰੱਖ ਸਕਣ ਵਾਲਾ, ਸੁਰਖ਼ਰੂ। ਹੋਵੈ = ਹੋਣਾ ਚਾਹੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-108", gurmukhi = "ਹੋਵੈ ਤ ਸਨਮੁਖੁ ਸਿਖੁ ਕੋਈ; ਜੀਅਹੁ ਰਹੈ ਗੁਰ ਨਾਲੇ ॥", transliteration = "hovai ta sanmukh sikh koee; jeeah rhai gur naale ||", translation = "if a Sikh turns to the Guru with sincere faith, as sunmukh, his soul abides with the Guru.", hindi = "होवै त सनमुखु सिखु कोई; जीअहु रहै गुर नाले ॥", punjabi = "ਜੋ ਸਿੱਖ ਇਹ ਚਾਹੁੰਦਾ ਹੈ ਕਿ ਕਿਸੇ ਲੁਕਵੇਂ ਖੋਟ ਦੇ ਕਾਰਨ ਉਸ ਨੂੰ ਗੁਰੂ ਦੇ ਸਾਹਮਣੇ ਅੱਖਾਂ ਨੀਵੀਆਂ ਨ ਕਰਨੀਆਂ ਪੈਣ, (ਤਾਂ ਰਸਤਾ ਇਕੋ ਹੀ ਹੈ ਕਿ) ਉਹ ਸੱਚੇ ਦਿਲੋਂ ਗੁਰੂ ਦੇ ਚਰਨਾਂ ਵਿਚ ਟਿਕੇ।", wordMeaning = "ਜੀਅਹੁ = ਦਿਲੋਂ। ਗੁਰ ਨਾਲੇ = ਗੁਰੂ ਦੇ ਚਰਨਾਂ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-109", gurmukhi = "ਗੁਰ ਕੇ ਚਰਨ. ਹਿਰਦੈ ਧਿਆਏ; ਅੰਤਰ ਆਤਮੈ ਸਮਾਲੇ ॥", transliteration = "gur ke charan. hirdai dhiaae; antar aatmai smaale ||", translation = "Within his heart, he meditates on the lotus feet of the Guru; deep within his soul, he contemplates Him.", hindi = "गुर के चरन. हिरदै धिआए; अंतर आतमै समाले ॥", punjabi = "ਸਿੱਖ ਗੁਰੂ ਦੇ ਚਰਨਾਂ ਨੂੰ ਆਪਣੇ ਹਿਰਦੇ ਵਿਚ ਥਾਂ ਦੇਵੇ, ਆਪਣੇ ਆਤਮਾ ਦੇ ਅੰਦਰ ਸੰਭਾਲ ਰੱਖੇ।", wordMeaning = "ਸਮਾਲੇ = ਯਾਦ ਰੱਖੇ, ਟਿਕਾਈ ਰੱਖੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-110", gurmukhi = "ਆਪੁ ਛਡਿ. ਸਦਾ ਰਹੈ ਪਰਣੈ; ਗੁਰ ਬਿਨੁ ਅਵਰੁ. ਨ ਜਾਣੈ ਕੋਏ ॥", transliteration = "aap chhad. sdaa rhai parnai; gur bin avar. na jaanai koe ||", translation = "Renouncing selfishness and conceit, he remains always on the side of the Guru; he does not know anyone except the Guru.", hindi = "आपु छडि. सदा रहै परणै; गुर बिनु अवरु. न जाणै कोए ॥", punjabi = "ਆਪਾ-ਭਾਵ ਛੱਡ ਕੇ ਸਦਾ ਗੁਰੂ ਦੇ ਆਸਰੇ, ਗੁਰੂ ਤੋਂ ਬਿਨਾ ਕਿਸੇ ਹੋਰ ਨੂੰ (ਆਪਣੇ ਆਤਮਕ ਜੀਵਨ ਦਾ, ਆਤਮਕ ਆਨੰਦ ਦਾ ਵਸੀਲਾ) ਨਾ ਸਮਝੇ।", wordMeaning = "ਆਪੁ = ਆਪਾ-ਭਾਵ। ਪਰਣੈ = ਆਸਰੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-111", gurmukhi = "ਕਹੈ ਨਾਨਕੁ. ਸੁਣਹੁ ਸੰਤਹੁ; ਸੋ ਸਿਖੁ ਸਨਮੁਖੁ ਹੋਏ ॥੨੧॥", transliteration = "kahai naanak. sunah santah; so sikh sanmukh hoe ||21||", translation = "Says Nanak, listen, O Saints: such a Sikh turns toward the Guru with sincere faith, and becomes sunmukh. ||21||", hindi = "कहै नानकु. सुणहु संतहु; सो सिखु सनमुखु होए ॥२१॥", punjabi = "ਨਾਨਕ ਆਖਦਾ ਹੈ ਕਿ ਹੇ ਸੰਤ ਜਨੋ! ਸੁਣੋ ਉਹ ਸਿੱਖ (ਹੀ) ਖਿੜੇ-ਮੱਥੇ ਰਹਿ ਸਕਦਾ ਹੈ (ਉਸ ਦੇ ਹੀ ਅੰਦਰ ਆਤਮਕ ਖੇੜਾ ਹੋ ਸਕਦਾ ਹੈ, ਉਹੀ ਆਤਮਕ ਆਨੰਦ ਮਾਣ ਸਕਦਾ ਹੈ) ॥੨੧॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-112", gurmukhi = "ਜੇ ਕੋ. ਗੁਰ ਤੇ ਵੇਮੁਖੁ ਹੋਵੈ; ਬਿਨੁ ਸਤਿਗੁਰ ਮੁਕਤਿ. ਨ ਪਾਵੈ ॥", transliteration = "je ko. gur te vemukh hovai; bin stigur mukat. na paavai ||", translation = "One who turns away from the Guru, and becomes baymukh - without the True Guru, he shall not find liberation.", hindi = "जे को. गुर ते वेमुखु होवै; बिनु सतिगुर मुकति. न पावै ॥", punjabi = "(ਜਿਥੇ ਮਾਇਆ ਦੇ ਮੋਹ ਦੇ ਕਾਰਨ ਸਹਿਮ ਹੈ ਉਥੇ ਆਤਮਕ ਆਨੰਦ ਨਹੀਂ ਪਲ੍ਹਰ ਸਕਦਾ, ਪਰ)  ਜੇ ਕੋਈ ਮਨੁੱਖ ਗੁਰੂ ਵਲੋਂ ਮੂੰਹ ਮੋੜ ਲਏ (ਉਸ ਨੂੰ ਆਤਮਕ ਆਨੰਦ ਨਸੀਬ ਨਹੀਂ ਹੋ ਸਕਦਾ ਕਿਉਂਕਿ) ਗੁਰੂ ਤੋਂ ਬਿਨਾ ਮਾਇਆ ਦੇ ਪ੍ਰਭਾਵ ਤੋਂ ਖ਼ਲਾਸੀ ਨਹੀਂ ਮਿਲਦੀ।", wordMeaning = "ਵੇਮੁਖੁ = ਜਿਸ ਨੇ ਮੂੰਹ ਦੂਜੇ ਪਾਸੇ ਕੀਤਾ ਹੋਇਆ ਹੈ। ਮੁਕਤਿ = ਵਿਕਾਰਾਂ ਤੋਂ ਖ਼ਲਾਸੀ, ਮਾਇਆ ਦੇ ਪ੍ਰਭਾਵ ਤੋਂ ਖ਼ਲਾਸੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-113", gurmukhi = "ਪਾਵੈ ਮੁਕਤਿ ਨ. ਹੋਰ ਥੈ ਕੋਈ; ਪੁਛਹੁ ਬਿਬੇਕੀਆ ਜਾਏ ॥", transliteration = "paavai mukat na. hor thai koee; puchhah bibekeeaa jaae ||", translation = "He shall not find liberation anywhere else either; go and ask the wise ones about this.", hindi = "पावै मुकति न. होर थै कोई; पुछहु बिबेकीआ जाए ॥", punjabi = "ਬੇਸ਼ੱਕ ਕਿਸੇ ਵਿਚਾਰਵਾਨਾਂ ਤੋਂ ਜਾ ਕੇ ਪੁੱਛ ਲਵੋ (ਤੇ ਤਸੱਲੀ ਕਰ ਲਵੋ, ਇਹ ਪੱਕੀ ਗੱਲ ਹੈ ਕਿ ਗੁਰੂ ਤੋਂ ਬਿਨਾ) ਕਿਸੇ ਭੀ ਹੋਰ ਥਾਂ ਤੋਂ ਮਾਇਕ ਬੰਧਨਾਂ ਤੋਂ ਖ਼ਲਾਸੀ ਨਹੀਂ ਮਿਲਦੀ।", wordMeaning = "ਹੋਰਥੈ = ਕਿਸੇ ਹੋਰ ਥਾਂ ਤੋਂ। ਬਿਬੇਕੀ = ਪਰਖ ਵਾਲਾ ਬੰਦਾ, ਵਿਚਾਰਵਾਨ। ਜਾਏ = ਜਾਇ, ਜਾ ਕੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-114", gurmukhi = "ਅਨੇਕ ਜੂਨੀ. ਭਰਮਿ ਆਵੈ; ਵਿਣੁ ਸਤਿਗੁਰ ਮੁਕਤਿ. ਨ ਪਾਏ ॥", transliteration = "anek joonee. bharam aavai; vin stigur mukat. na paae ||", translation = "He shall wander through countless incarnations; without the True Guru, he shall not find liberation.", hindi = "अनेक जूनी. भरमि आवै; विणु सतिगुर मुकति. न पाए ॥", punjabi = "(ਮਾਇਆ ਦੇ ਮੋਹ ਵਿਚ ਫਸਿਆ ਮਨੁੱਖ) ਅਨੇਕਾਂ ਜੂਨੀਆਂ ਵਿਚ ਭਟਕਦਾ ਆਉਂਦਾ ਹੈ, ਗੁਰੂ ਦੀ ਸਰਨ ਤੋਂ ਬਿਨਾ ਇਸ ਮੋਹ ਤੋਂ ਖ਼ਲਾਸੀ ਨਹੀਂ ਮਿਲਦੀ।", wordMeaning = "ਭਰਮਿ ਆਵੈ = ਭਟਕ ਕੇ ਆਉਂਦਾ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-115", gurmukhi = "ਫਿਰਿ ਮੁਕਤਿ ਪਾਏ. ਲਾਗਿ ਚਰਣੀ; ਸਤਿਗੁਰੂ ਸਬਦੁ ਸੁਣਾਏ ॥", transliteration = "phir mukat paae. laag charnee; stiguroo sabad sunaae ||", translation = "But liberation is attained, when one is attached to the feet of the True Guru, chanting the Word of the Shabad.", hindi = "फिरि मुकति पाए. लागि चरणी; सतिगुरू सबदु सुणाए ॥", punjabi = "ਆਖ਼ਰ ਗੁਰੂ ਦੀ ਚਰਨੀਂ ਲੱਗ ਕੇ ਹੀ ਮਾਇਆ ਦੇ ਮੋਹ ਤੋਂ ਛੁਟਕਾਰਾ ਮਿਲਦਾ ਹੈ ਕਿਉਂਕਿ ਗੁਰੂ (ਸਹੀ ਜੀਵਨ-ਮਾਰਗ ਦਾ) ਉਪਦੇਸ਼ ਸੁਣਾਂਦਾ ਹੈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-116", gurmukhi = "ਕਹੈ ਨਾਨਕੁ. ਵੀਚਾਰਿ ਦੇਖਹੁ; ਵਿਣੁ ਸਤਿਗੁਰ ਮੁਕਤਿ. ਨ ਪਾਏ ॥੨੨॥", transliteration = "kahai naanak. veechaar dekhah; vin stigur mukat. na paae ||22||", translation = "Says Nanak, contemplate this and see, that without the True Guru, there is no liberation. ||22||", hindi = "कहै नानकु. वीचारि देखहु; विणु सतिगुर मुकति. न पाए ॥२२॥", punjabi = "ਨਾਨਕ ਆਖਦਾ ਹੈ ਕਿ ਵਿਚਾਰ ਕੇ ਵੇਖ ਲਵੋ, ਗੁਰੂ ਤੋਂ ਬਿਨਾ ਮਾਇਆ ਦੇ ਬੰਧਨ ਤੋਂ ਆਜ਼ਾਦੀ ਨਹੀਂ ਮਿਲਦੀ, (ਤੇ ਇਸ ਮੁਕਤੀ ਤੋਂ ਬਿਨਾ ਆਤਮਕ ਆਨੰਦ ਦੀ ਪ੍ਰਾਪਤੀ ਨਹੀਂ ਹੋ ਸਕਦੀ) ॥੨੨॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-117", gurmukhi = "ਆਵਹੁ ਸਿਖ. ਸਤਿਗੁਰੂ ਕੇ ਪਿਆਰਿਹੋ; ਗਾਵਹੁ ਸਚੀ ਬਾਣੀ ॥", transliteration = "aavah sikh. stiguroo ke piaariho; gaavah schee baanee ||", translation = "Come, O beloved Sikhs of the True Guru, and sing the True Word of His Bani.", hindi = "आवहु सिख. सतिगुरू के पिआरिहो; गावहु सची बाणी ॥", punjabi = "ਹੇ ਸਤਿਗੁਰੂ ਦੇ ਪਿਆਰੇ ਸਿੱਖੋ! ਆਵੋ, ਸਦਾ-ਥਿਰ ਰਹਿਣ ਵਾਲੇ ਪਰਮਾਤਮਾ ਵਿਚ ਜੋੜਨ ਵਾਲੀ ਬਾਣੀ (ਰਲ ਕੇ) ਗਾਵੋ।", wordMeaning = "ਸਚੀ ਬਾਣੀ = ਪਰਮਾਤਮਾ ਦੀ ਸਿਫ਼ਤ-ਸਾਲਾਹ ਵਾਲੀ ਬਾਣੀ, ਸਦਾ-ਥਿਰ ਰਹਿਣ ਵਾਲੇ ਪ੍ਰਭੂ ਵਿਚ ਜੋੜਨ ਵਾਲੀ ਬਾਣੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-118", gurmukhi = "ਬਾਣੀ ਤ ਗਾਵਹੁ ਗੁਰੂ ਕੇਰੀ; ਬਾਣੀਆ ਸਿਰਿ ਬਾਣੀ ॥", transliteration = "baanee ta gaavah guroo keree; baaneeaa sir baanee ||", translation = "Sing the Guru's Bani, the supreme Word of Words.", hindi = "बाणी त गावहु गुरू केरी; बाणीआ सिरि बाणी ॥", punjabi = "ਆਪਣੇ ਗੁਰੂ ਦੀ ਬਾਣੀ ਗਾਵੋ, ਇਹ ਬਾਣੀ ਹੋਰ ਸਭ ਬਾਣੀਆਂ ਨਾਲੋਂ ਸ਼ਿਰੋਮਣੀ ਹੈ।", wordMeaning = "ਸਿਰ = ਸਿਰ ਉਤੇ, ਸਭ ਤੋਂ ਸ੍ਰੇਸ਼ਟ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-119", gurmukhi = "ਜਿਨ ਕਉ ਨਦਰਿ ਕਰਮੁ ਹੋਵੈ; ਹਿਰਦੈ ਤਿਨਾ ਸਮਾਣੀ ॥", transliteration = "jin kau nadar karam hovai; hirdai tinaa smaanee ||", translation = "Those who are blessed by the Lord's Glance of Grace - their hearts are imbued with this Bani.", hindi = "जिन कउ नदरि करमु होवै; हिरदै तिना समाणी ॥", punjabi = "ਇਹ ਬਾਣੀ ਉਹਨਾਂ ਬੰਦਿਆਂ ਦੇ ਹਿਰਦੇ ਵਿਚ ਹੀ ਟਿਕਦੀ ਹੈ ਜਿਨ੍ਹਾਂ ਉਤੇ ਪਰਮਾਤਮਾ ਦੀ ਮੇਹਰ ਦੀ ਨਜ਼ਰ ਹੋਵੇ, ਬਖ਼ਸ਼ਸ਼ ਹੋਵੇ।", wordMeaning = "ਨਦਰਿ = ਮੇਹਰ ਦੀ ਨਜ਼ਰ। ਕਰਮੁ = ਬਖ਼ਸ਼ਸ਼।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-120", gurmukhi = "ਪੀਵਹੁ ਅੰਮ੍ਰਿਤੁ. ਸਦਾ ਰਹਹੁ ਹਰਿ ਰੰਗਿ; ਜਪਿਹੁ ਸਾਰਿਗਪਾਣੀ ॥", transliteration = "peevah amrit. sdaa rahah har rang; jpih saarigpaanee ||", translation = "Drink in this Ambrosial Nectar, and remain in the Lord's Love forever; meditate on the Lord, the Sustainer of the world.", hindi = "पीवहु अंम्रितु. सदा रहहु हरि रंगि; जपिहु सारिगपाणी ॥", punjabi = "(ਹੇ ਪਿਆਰੇ ਗੁਰਸਿੱਖੋ!) ਪਰਮਾਤਮਾ ਦਾ ਨਾਮ ਸਿਮਰੋ, ਪਰਮਾਤਮਾ ਦੇ ਪਿਆਰ ਵਿਚ ਸਦਾ ਜੁੜੇ ਰਹੋ, ਇਹ (ਆਨੰਦ ਦੇਣ ਵਾਲਾ, ਆਤਮਕ ਹੁਲਾਰਾ ਪੈਦਾ ਕਰਨ ਵਾਲਾ) ਨਾਮ-ਜਲ ਪੀਓ।", wordMeaning = "ਹਰਿ ਰੰਗਿ = ਹਰੀ ਦੇ ਪਿਆਰ ਵਿਚ। ਸਾਰਿਗ ਪਾਣੀ = ਧਨੁਖਧਾਰੀ ਪ੍ਰਭੂ। ਕੇਰੀ = ਦੀ। ਅੰਮ੍ਰਿਤ = ਆਤਮਕ ਆਨੰਦ ਦੇਣ ਵਾਲਾ ਨਾਮ-ਜਲ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-121", gurmukhi = "ਕਹੈ ਨਾਨਕੁ. ਸਦਾ ਗਾਵਹੁ; ਏਹ ਸਚੀ ਬਾਣੀ ॥੨੩॥", transliteration = "kahai naanak. sdaa gaavah; eh schee baanee ||23||", translation = "Says Nanak, sing this True Bani forever. ||23||", hindi = "कहै नानकु. सदा गावहु; एह सची बाणी ॥२३॥", punjabi = "ਨਾਨਕ ਆਖਦਾ ਹੈ ਕਿ (ਹੇ ਗੁਰਸਿੱਖੋ!) ਪਰਮਾਤਮਾ ਦੀ ਸਿਫ਼ਤ-ਸਾਲਾਹ ਵਾਲੀ ਇਹ ਬਾਣੀ ਸਦਾ ਗਾਵੋ (ਇਸੇ ਵਿਚ ਆਤਮਕ ਆਨੰਦ ਹੈ) ॥੨੩॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-122", gurmukhi = "ਸਤਿਗੁਰੂ ਬਿਨਾ; ਹੋਰ ਕਚੀ ਹੈ ਬਾਣੀ ॥", transliteration = "satiguroo binaa; hor kchee hai baanee ||", translation = "Without the True Guru, other songs are false.", hindi = "सतिगुरू बिना; होर कची है बाणी ॥", punjabi = "ਗੁਰ-ਆਸ਼ੇ ਤੋਂ ਉਲਟ ਬਾਣੀ (ਮਾਇਆ) ਦੀ ਝਲਕ ਦੇ ਸਾਹਮਣੇ ਥਿੜਕਾ ਦੇਣ ਵਾਲੀ ਹੁੰਦੀ ਹੈ।", wordMeaning = "ਸਤਿਗੁਰੂ ਬਿਨਾ = ਗੁਰ-ਆਸ਼ੇ ਤੋਂ ਉਲਟ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-123", gurmukhi = "ਬਾਣੀ ਤ ਕਚੀ. ਸਤਿਗੁਰੂ ਬਾਝਹੁ; ਹੋਰ ਕਚੀ ਬਾਣੀ ॥", transliteration = "baanee ta kchee. stiguroo baajhah; hor kchee baanee ||", translation = "The songs are false without the True Guru; all other songs are false.", hindi = "बाणी त कची. सतिगुरू बाझहु; होर कची बाणी ॥", punjabi = "ਗੁਰ-ਆਸ਼ੇ ਤੋਂ ਉਲਟ ਬਾਣੀ ਮਨੁੱਖ ਦੇ ਮਨ ਨੂੰ ਆਤਮਕ ਆਨੰਦ ਦੇ ਟਿਕਾਣੇ ਤੋਂ ਹੇਠਾਂ ਡੇਗਦੀ ਹੈ।", wordMeaning = "ਕਚੀ = ਹੌਲੇ ਮੇਲ ਦੀ, ਮਨ ਨੂੰ ਨੀਵਾਂ ਕਰਨ ਵਾਲੀ, ਉੱਚੇ ਆਤਮਕ ਆਨੰਦ ਤੋਂ ਹੇਠਾਂ ਲਿਆਉਣ ਵਾਲੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-124", gurmukhi = "ਕਹਦੇ ਕਚੇ; ਸੁਣਦੇ ਕਚੇ; ਕਚਂ‍ੀ ਆਖਿ ਵਖਾਣੀ ॥", transliteration = "kahde kche; sunde kche; kachan‍ee aakh vkhaanee ||", translation = "The speakers are false, and the listeners are false; those who speak and recite are false.", hindi = "कहदे कचे; सुणदे कचे; कचं‍ी आखि वखाणी ॥", punjabi = "ਇਹ ਪੱਕੀ ਗੱਲ ਹੈ ਕਿ ਗੁਰ-ਆਸ਼ੇ ਦੇ ਉਲਟ ਜਾਣ ਵਾਲੀ ਬਾਣੀ ਨੂੰ ਸੁਣਨ ਵਾਲਿਆਂ ਦੇ ਮਨ ਕਮਜ਼ੋਰ ਹੋ ਜਾਂਦੇ ਹਨ, ਸੁਣਨ ਵਾਲਿਆਂ ਦੇ ਮਨ ਭੀ ਥਿੜਕ ਜਾਂਦੇ ਹਨ, ਤੇ ਜੋ ਅਜੇਹੀ ਬਾਣੀ ਦੀ ਪੜ੍ਹ ਪੜ੍ਹ ਕੇ ਵਿਆਖਿਆ ਕਰਦੇ ਹਨ, ਉਹ ਭੀ ਕਮਜ਼ੋਰ ਮਨ ਦੇ ਹੋ ਜਾਂਦੇ ਹਨ।", wordMeaning = "ਕਚੇ = ਉਹ ਬੰਦੇ ਜਿਨ੍ਹਾਂ ਦਾ ਮਨ ਕਮਜ਼ੋਰ ਹੈ, ਜੋ ਮਾਇਆ ਦੇ ਪ੍ਰਭਾਵ ਦੇ ਸਾਹਮਣੇ ਥਿੜਕ ਸਕਦੇ ਹਨ। ਸੁਣਦੇ ਕਚੇ = ਸੁਣਨ ਵਾਲਿਆਂ ਦੇ ਮਨ ਭੀ ਥਿੜਕ ਜਾਂਦੇ ਹਨ।", startsAtMs = 0L, endsAtMs = 0L),
