    BaniLine(id = "anand-sahib-135", gurmukhi = "ਤੋੜੇ ਬੰਧਨ. ਹੋਵੈ ਮੁਕਤੁ; ਸਬਦੁ ਮੰਨਿ ਵਸਾਏ ॥", transliteration = "tore bandhan. hovai mukat; sabad mann vsaae ||", translation = "They break their bonds, and attain liberation; they enshrine the Shabad within their minds.", hindi = "तोड़े बंधन. होवै मुकतु; सबदु मंनि वसाए ॥", punjabi = "(ਜਿਸ ਨੂੰ ਸੂਝ ਬਖ਼ਸ਼ਦਾ ਹੈ ਉਸ ਦੇ) ਮਾਇਆ (ਦੇ ਮੋਹ) ਦੇ ਬੰਧਨ ਤੋੜ ਦੇਂਦਾ ਹੈ, ਉਹ ਬੰਦਾ ਮਾਇਆ ਦੇ ਬੰਧਨਾਂ ਤੋਂ ਸੁਤੰਤਰ ਹੋ ਜਾਂਦਾ ਹੈ (ਕਿਉਂਕਿ) ਉਹ ਗੁਰੂ ਦਾ ਸ਼ਬਦ ਆਪਣੇ ਮਨ ਵਿਚ ਵਸਾ ਲੈਂਦਾ ਹੈ।", wordMeaning = "ਮੁਕਤੁ = ਮਾਇਆ ਦੇ ਪ੍ਰਭਾਵ ਤੋਂ ਆਜ਼ਾਦ ਸੁਤੰਤਰ। ਮੰਨਿ = ਮਨ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-136", gurmukhi = "ਗੁਰਮੁਖਿ ਜਿਸ ਨੋ ਆਪਿ ਕਰੇ ਸੁ ਹੋਵੈ; ਏਕਸ ਸਿਉ ਲਿਵ ਲਾਏ ॥", transliteration = "gurmukh jis no aap kre su hovai; ekas siu liv laae ||", translation = "Those whom the Lord Himself makes Gurmukh, lovingly focus their consciousness on the One Lord.", hindi = "गुरमुखि जिस नो आपि करे सु होवै; एकस सिउ लिव लाए ॥", punjabi = "ਗੁਰੂ ਦੇ ਦੱਸੇ ਰਾਹ ਉਤੇ ਤੁਰਨ ਜੋਗਾ ਉਹੀ ਮਨੁੱਖ ਹੁੰਦਾ ਹੈ ਜਿਸ ਨੂੰ ਪ੍ਰਭੂ ਇਹ ਸਮਰੱਥਾ ਦੇਂਦਾ ਹੈ, ਉਹ ਮਨੁੱਖ ਇਕ ਪਰਮਾਤਮਾ ਦੇ ਚਰਨਾਂ ਵਿਚ ਸੁਰਤ ਜੋੜਦਾ ਹੈ (ਉਸ ਦੇ ਅੰਦਰ ਆਤਮਕ ਆਨੰਦ ਬਣਦਾ ਹੈ, ਤੇ ਉਹ ਮਾਇਆ ਦੇ ਮੋਹ ਵਿਚੋਂ ਨਿਕਲਦਾ ਹੈ)।", wordMeaning = "ਗੁਰਮੁਖਿ = ਗੁਰੂ ਦੇ ਰਾਹ ਉਤੇ ਤੁਰਨ ਵਾਲਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-137", gurmukhi = "ਕਹੈ ਨਾਨਕੁ. ਆਪਿ ਕਰਤਾ; ਆਪੇ ਹੁਕਮੁ ਬੁਝਾਏ ॥੨੬॥", transliteration = "kahai naanak. aap kartaa; aape hukam bujhaae ||26||", translation = "Says Nanak, He Himself is the Creator; He Himself reveals the Hukam of His Command. ||26||", hindi = "कहै नानकु. आपि करता; आपे हुकमु बुझाए ॥२६॥", punjabi = "ਨਾਨਕ ਆਖਦਾ ਹੈ ਕਿ ਪਰਮਾਤਮਾ ਆਪ ਹੀ (ਜੀਵਾਤਮਾ ਤੇ ਮਾਇਆ ਦੀ) ਰਚਨਾ ਕਰਦਾ ਹੈ ਤੇ ਆਪ ਹੀ (ਕਿਸੇ ਵਿਰਲੇ ਨੂੰ ਇਹ) ਸੂਝ ਬਖ਼ਸ਼ਦਾ ਹੈ (ਕਿ ਮਾਇਆ ਦਾ ਪ੍ਰਭਾਵ ਭੀ ਉਸ ਦਾ ਆਪਣਾ ਹੀ) ਹੁਕਮ (ਜਗਤ ਵਿਚ ਵਰਤ ਰਿਹਾ) ਹੈ ॥੨੬॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-138", gurmukhi = "ਸਿਮ੍ਰਿਤਿ ਸਾਸਤ੍ਰ. ਪੁੰਨ ਪਾਪ ਬੀਚਾਰਦੇ; ਤਤੈ ਸਾਰ. ਨ ਜਾਣੀ ॥", transliteration = "simrit saasatr. punn paap beechaarde; ttai saar. na jaanee ||", translation = "The Simritees and the Shaastras discriminate between good and evil, but they do not know the true essence of reality.", hindi = "सिम्रिति सासत्र. पुंन पाप बीचारदे; ततै सार. न जाणी ॥", punjabi = "ਸਿੰਮ੍ਰਿਤੀਆਂ ਸ਼ਾਸਤ੍ਰ ਆਦਿਕ ਪੜ੍ਹਨ ਵਾਲੇ ਪੰਡਿਤ ਸਿਰਫ਼ ਇਹੀ ਵਿਚਾਰਾਂ ਕਰਦੇ ਹਨ ਕਿ (ਇਹਨਾਂ ਪੁਸਤਕਾਂ ਅਨੁਸਾਰ) ਪਾਪ ਕੀਹ ਹੈ ਤੇ ਪੁੰਨ ਕੀਹ ਹੈ, ਉਹਨਾਂ ਨੂੰ ਆਤਮਕ ਆਨੰਦ ਦਾ ਰਸ ਨਹੀਂ ਆ ਸਕਦਾ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-139", gurmukhi = "ਤਤੈ ਸਾਰ. ਨ ਜਾਣੀ ਗੁਰੂ ਬਾਝਹੁ; ਤਤੈ ਸਾਰ. ਨ ਜਾਣੀ ॥", transliteration = "tatai saar. na jaanee guroo baajhah; ttai saar. na jaanee ||", translation = "They do not know the true essence of reality without the Guru; they do not know the true essence of reality.", hindi = "ततै सार. न जाणी गुरू बाझहु; ततै सार. न जाणी ॥", punjabi = "(ਇਹ ਗੱਲ ਯਕੀਨੀ ਜਾਣੋ ਕਿ) ਸਤਿਗੁਰੂ ਦੀ ਸਰਨ ਆਉਣ ਤੋਂ ਬਿਨਾ ਆਤਮਕ ਆਨੰਦ ਦਾ ਰਸ ਨਹੀਂ ਆ ਸਕਦਾ।", wordMeaning = "ਤਤੈ ਸਾਰ = ਤੱਤ ਦੀ ਸੂਝ, ਅਸਲੀਅਤ ਦੀ ਸਮਝ, ਜੋ ਅਸਲ ਗ੍ਰਹਿਣ = ਜੋਗ ਵਸਤ ਹੈ ਉਸ ਦੀ ਸਮਝ, ਆਤਮਕ ਆਨੰਦ ਦੀ ਸਮਝ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-140", gurmukhi = "ਤਿਹੀ ਗੁਣੀ ਸੰਸਾਰੁ. ਭ੍ਰਮਿ ਸੁਤਾ; ਸੁਤਿਆ ਰੈਣਿ ਵਿਹਾਣੀ ॥", transliteration = "tihee gunee sansaar. bhram sutaa; sutiaa rain vihaanee ||", translation = "The world is asleep in the three modes and doubt; it passes the night of its life sleeping.", hindi = "तिही गुणी संसारु. भ्रमि सुता; सुतिआ रैणि विहाणी ॥", punjabi = "ਜਗਤ ਤਿੰਨਾਂ ਗੁਣਾਂ ਵਿਚ ਹੀ ਭਟਕ ਭਟਕ ਕੇ ਗ਼ਾਫ਼ਿਲ ਹੋਇਆ ਪਿਆ ਹੈ, ਮਾਇਆ ਦੇ ਮੋਹ ਵਿਚ ਸੁੱਤਿਆਂ ਦੀ ਹੀ ਸਾਰੀ ਉਮਰ ਗੁਜ਼ਰ ਜਾਂਦੀ ਹੈ (ਸਿੰਮ੍ਰਿਤੀਆਂ ਸ਼ਾਸਤ੍ਰਾਂ ਦੀਆਂ ਵਿਚਾਰਾਂ ਇਸ ਨੀਂਦ ਵਿਚੋਂ ਜਗਾ ਨਹੀਂ ਸਕਦੀਆਂ)।", wordMeaning = "ਤਿਹੀ ਗੁਣੀ = ਮਾਇਆ ਦੇ ਤਿੰਨ ਸੁਭਾਵਾਂ ਵਿਚ। ਭ੍ਰਮਿ = ਭਟਕ ਭਟਕ ਕੇ। ਰੈਣਿ = ਉਮਰ, ਰਾਤ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-141", gurmukhi = "ਗੁਰ ਕਿਰਪਾ ਤੇ. ਸੇ ਜਨ ਜਾਗੇ. ਜਿਨਾ ਹਰਿ ਮਨਿ ਵਸਿਆ; ਬੋਲਹਿ ਅੰਮ੍ਰਿਤ ਬਾਣੀ ॥", transliteration = "gur kirpaa te. se jan jaage. jinaa har man vsiaa; bolah amrit baanee ||", translation = "Those humble beings remain awake and aware, within whose minds, by Guru's Grace, the Lord abides; they chant the Ambrosial Word of the Guru's Bani.", hindi = "गुर किरपा ते. से जन जागे. जिना हरि मनि वसिआ; बोलहि अंम्रित बाणी ॥", punjabi = "(ਮੋਹ ਦੀ ਨੀਂਦ ਵਿਚੋਂ) ਗੁਰੂ ਦੀ ਕਿਰਪਾ ਨਾਲ (ਸਿਰਫ਼) ਉਹ ਮਨੁੱਖ ਜਾਗਦੇ ਹਨ ਜਿਨ੍ਹਾਂ ਦੇ ਅੰਦਰ ਪਰਮਾਤਮਾ ਦਾ ਨਾਮ ਵੱਸਦਾ ਹੈ ਜੋ ਪਰਮਾਤਮਾ ਦੀ ਸਿਫ਼ਤ-ਸਾਲਾਹ ਦੀ ਬਾਣੀ ਉਚਾਰਦੇ ਹਨ।", wordMeaning = "ਸੇ = ਉਹ ਬੰਦੇ। ਮਨਿ = ਮਨ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-142", gurmukhi = "ਕਹੈ ਨਾਨਕੁ. ਸੋ ਤਤੁ ਪਾਏ. ਜਿਸ ਨੋ ਅਨਦਿਨੁ ਹਰਿ ਲਿਵ ਲਾਗੈ; ਜਾਗਤ ਰੈਣਿ ਵਿਹਾਣੀ ॥੨੭॥", transliteration = "kahai naanak. so tat paae. jis no andin har liv laagai; jaagat rain vihaanee ||27||", translation = "Says Nanak, they alone obtain the essence of reality, who night and day remain lovingly absorbed in the Lord; they pass the night of their life awake and aware. ||27||", hindi = "कहै नानकु. सो ततु पाए. जिस नो अनदिनु हरि लिव लागै; जागत रैणि विहाणी ॥२७॥", punjabi = "ਨਾਨਕ ਆਖਦਾ ਹੈ ਕਿ ਉਹੀ ਮਨੁੱਖ ਆਤਮਕ ਆਨੰਦ ਮਾਣਦਾ ਹੈ ਜੋ ਹਰ ਵੇਲੇ ਪ੍ਰਭੂ ਦੀ ਯਾਦ ਦੀ ਲਗਨ ਵਿਚ ਟਿਕਿਆ ਰਹਿੰਦਾ ਹੈ, ਤੇ ਜਿਸ ਦੀ ਉਮਰ (ਇਸ ਤਰ੍ਹਾਂ ਮੋਹ ਦੀ ਨੀਂਦ ਵਿਚੋਂ) ਜਾਗਦਿਆਂ ਬੀਤਦੀ ਹੈ ॥੨੭॥", wordMeaning = "ਅਨਦਿਨੁ = ਹਰ ਰੋਜ਼, ਹਰ ਵੇਲੇ। ਅੰਮ੍ਰਿਤ ਬਾਣੀ = ਆਤਮਕ ਜੀਵਨ ਦੇਣ ਵਾਲੀ ਬਾਣੀ। ਜਾਗਤ = ਵਿਕਾਰਾਂ ਵਲੋਂ ਸੁਚੇਤ ਰਹਿੰਦਿਆਂ ॥੨੭॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-143", gurmukhi = "ਮਾਤਾ ਕੇ ਉਦਰ ਮਹਿ. ਪ੍ਰਤਿਪਾਲ ਕਰੇ; ਸੋ. ਕਿਉ ਮਨਹੁ ਵਿਸਾਰੀਐ ॥", transliteration = "maataa ke udar mah. pratipaal kre; so. kiu manah visaareeai ||", translation = "He nourished us in the mother's womb; why forget Him from the mind?", hindi = "माता के उदर महि. प्रतिपाल करे; सो. किउ मनहु विसारीऐ ॥", punjabi = "(ਜੇ ਆਤਮਕ ਆਨੰਦ ਪ੍ਰਾਪਤ ਕਰਨਾ ਹੈ ਤਾਂ) ਉਸ ਪਰਮਾਤਮਾ ਨੂੰ ਕਦੇ ਭੁਲਾਣਾ ਨਹੀਂ ਚਾਹੀਦਾ, ਜੋ ਮਾਂ ਦੇ ਪੇਟ ਵਿਚ (ਭੀ) ਪਾਲਣਾ ਕਰਦਾ ਹੈ।", wordMeaning = "ਉਦਰ = ਪੇਟ। ਮਨਹੁ = ਮਨ ਤੋਂ। ਕਿਉ ਵਿਸਾਰੀਐ = ਵਿਸਾਰਨਾ ਨਹੀਂ ਚਾਹੀਦਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-144", gurmukhi = "ਮਨਹੁ. ਕਿਉ ਵਿਸਾਰੀਐ, ਏਵਡੁ ਦਾਤਾ; ਜਿ ਅਗਨਿ ਮਹਿ. ਆਹਾਰੁ ਪਹੁਚਾਵਏ ॥", transliteration = "manah. kiu visaareeai, evad daataa; ji agan mah. aahaar phuchaavae ||", translation = "Why forget from the mind such a Great Giver, who gave us sustenance in the fire of the womb?", hindi = "मनहु. किउ विसारीऐ, एवडु दाता; जि अगनि महि. आहारु पहुचावए ॥", punjabi = "ਇਤਨੇ ਵੱਡੇ ਦਾਤੇ ਨੂੰ ਮਨੋਂ ਭੁਲਾਣਾ ਨਹੀਂ ਚਾਹੀਦਾ ਜੋ (ਮਾਂ ਦੇ ਪੇਟ ਦੀ) ਅੱਗ ਵਿਚ (ਭੀ) ਖ਼ੁਰਾਕ ਅਪੜਾਂਦਾ ਹੈ।", wordMeaning = "ਏਵਡੁ = ਇਤਨਾ ਵੱਡਾ। ਅਗਨਿ = ਅੱਗ। ਆਹਾਰੁ = ਖ਼ੁਰਾਕ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-145", gurmukhi = "ਓਸ ਨੋ ਕਿਹੁ ਪੋਹਿ. ਨ ਸਕੀ; ਜਿਸ ਨਉ ਆਪਣੀ ਲਿਵ ਲਾਵਏ ॥", transliteration = "os no kih poh. na skee; jis nau aapnee liv laavae ||", translation = "Nothing can harm one, whom the Lord inspires to embrace His Love.", hindi = "ओस नो किहु पोहि. न सकी; जिस नउ आपणी लिव लावए ॥", punjabi = "(ਇਹ ਮੋਹ ਹੀ ਹੈ ਜੋ ਆਨੰਦ ਤੋਂ ਵਾਂਜਿਆਂ ਰੱਖਦਾ ਹੈ, ਪਰ) ਉਸ ਬੰਦੇ ਨੂੰ (ਮੋਹ ਆਦਿਕ) ਕੁਝ ਭੀ ਪੋਹ ਨਹੀਂ ਸਕਦਾ ਜਿਸ ਨੂੰ ਪ੍ਰਭੂ ਆਪਣੇ ਚਰਨਾਂ ਦੀ ਪ੍ਰੀਤ ਬਖ਼ਸ਼ਦਾ ਹੈ।", wordMeaning = "ਓਸ ਨੋ = ਉਸ ਬੰਦੇ ਨੂੰ। ਕਿਹੁ = ਕੁਝ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-146", gurmukhi = "ਆਪਣੀ ਲਿਵ ਆਪੇ ਲਾਏ; ਗੁਰਮੁਖਿ ਸਦਾ ਸਮਾਲੀਐ ॥", transliteration = "aapnee liv aape laae; gurmukh sdaa smaaleeai ||", translation = "He Himself is the love, and He Himself is the embrace; the Gurmukh contemplates Him forever.", hindi = "आपणी लिव आपे लाए; गुरमुखि सदा समालीऐ ॥", punjabi = "(ਪਰ ਜੀਵ ਦੇ ਕੀਹ ਵੱਸ?) ਪ੍ਰਭੂ ਆਪ ਹੀ ਆਪਣੀ ਪ੍ਰੀਤ ਦੀ ਦਾਤ ਦੇਂਦਾ ਹੈ। ਗੁਰੂ ਦੀ ਸਰਨ ਪੈ ਕੇ ਉਸ ਨੂੰ ਸਿਮਰਦੇ ਰਹਿਣਾ ਚਾਹੀਦਾ ਹੈ।", wordMeaning = "ਲਿਵ = ਪ੍ਰੀਤ। ਗੁਰਮੁਖਿ = ਗੁਰੂ ਦੀ ਰਾਹੀਂ। ਸਮਾਲੀਐ = ਸਿਮਰਨਾ ਚਾਹੀਦਾ ਹੈ, ਹਿਰਦੇ ਵਿਚ ਵਸਾਣਾ ਚਾਹੀਦਾ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-147", gurmukhi = "ਕਹੈ ਨਾਨਕੁ. ਏਵਡੁ ਦਾਤਾ; ਸੋ. ਕਿਉ ਮਨਹੁ ਵਿਸਾਰੀਐ ॥੨੮॥", transliteration = "kahai naanak. evad daataa; so. kiu manah visaareeai ||28||", translation = "Says Nanak, why forget such a Great Giver from the mind? ||28||", hindi = "कहै नानकु. एवडु दाता; सो. किउ मनहु विसारीऐ ॥२८॥", punjabi = "ਨਾਨਕ ਆਖਦਾ ਹੈ ਕਿ (ਜੇ ਆਤਮਕ ਆਨੰਦ ਦੀ ਲੋੜ ਹੈ ਤਾਂ) ਇਤਨੇ ਵੱਡੇ ਦਾਤਾਰ ਪ੍ਰਭੂ ਨੂੰ ਕਦੇ ਭੀ ਭੁਲਾਣਾ ਨਹੀਂ ਚਾਹੀਦਾ ॥੨੮॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-148", gurmukhi = "ਜੈਸੀ ਅਗਨਿ ਉਦਰ ਮਹਿ; ਤੈਸੀ ਬਾਹਰਿ ਮਾਇਆ ॥", transliteration = "jaisee agan udar mah; taisee baahar maaiaa ||", translation = "As is the fire within the womb, so is Maya outside.", hindi = "जैसी अगनि उदर महि; तैसी बाहरि माइआ ॥", punjabi = "ਜਿਵੇਂ ਮਾਂ ਦੇ ਪੇਟ ਵਿਚ ਅੱਗ ਹੈ ਤਿਵੇਂ ਬਾਹਰ ਜਗਤ ਵਿਚ ਮਾਇਆ (ਦੁਖਦਾਈ) ਹੈ।", wordMeaning = "ਉਦਰ = ਮਾਂ ਦਾ ਪੇਟ। ਬਾਹਰਿ = ਸੰਸਾਰ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-149", gurmukhi = "ਮਾਇਆ ਅਗਨਿ ਸਭ ਇਕੋ ਜੇਹੀ; ਕਰਤੈ ਖੇਲੁ ਰਚਾਇਆ ॥", transliteration = "maaiaa agan sabh iko jehee; kartai khel rchaaiaa ||", translation = "The fire of Maya is one and the same; the Creator has staged this play.", hindi = "माइआ अगनि सभ इको जेही; करतै खेलु रचाइआ ॥", punjabi = "ਮਾਇਆ ਤੇ ਅੱਗ ਇਕੋ ਜਿਹੀਆਂ ਹੀ ਹਨ, ਕਰਤਾਰ ਨੇ ਐਸੀ ਹੀ ਖੇਡ ਰਚ ਦਿੱਤੀ ਹੈ।", wordMeaning = "ਕਰਤੈ = ਕਰਤਾਰ ਨੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-150", gurmukhi = "ਜਾ ਤਿਸੁ ਭਾਣਾ. ਤਾ ਜੰਮਿਆ; ਪਰਵਾਰਿ ਭਲਾ ਭਾਇਆ ॥", transliteration = "jaa tis bhaanaa. taa jammiaa; parvaar bhlaa bhaaiaa ||", translation = "According to His Will, the child is born, and the family is very pleased.", hindi = "जा तिसु भाणा. ता जंमिआ; परवारि भला भाइआ ॥", punjabi = "ਜਦੋਂ ਪਰਮਾਤਮਾ ਦੀ ਰਜ਼ਾ ਹੁੰਦੀ ਹੈ ਜੀਵ ਪੈਦਾ ਹੁੰਦਾ ਹੈ ਪਰਵਾਰ ਵਿਚ ਪਿਆਰਾ ਲੱਗਦਾ ਹੈ।", wordMeaning = "ਜਾ ਤਿਸੁ ਭਾਣਾ = ਜਦੋਂ ਉਸ ਪ੍ਰਭੂ ਨੂੰ ਚੰਗਾ ਲੱਗਾ। ਪਰਵਾਰਿ = ਪਰਵਾਰ ਵਿਚ। ਭਲਾ ਭਾਇਆ = ਪਿਆਰਾ ਲੱਗਣ ਲੱਗ ਪਿਆ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-151", gurmukhi = "ਲਿਵ ਛੁੜਕੀ. ਲਗੀ ਤ੍ਰਿਸਨਾ; ਮਾਇਆ. ਅਮਰੁ ਵਰਤਾਇਆ ॥", transliteration = "liv chhurkee. lgee trisnaa; maaiaa. amar vartaaiaa ||", translation = "Love for the Lord wears off, and the child becomes attached to desires; the script of Maya runs its course.", hindi = "लिव छुड़की. लगी त्रिसना; माइआ. अमरु वरताइआ ॥", punjabi = "(ਪਰਵਾਰ ਦੇ ਜੀਵ ਉਸ ਨਵੇਂ ਜੰਮੇ ਬਾਲ ਨੂੰ ਪਿਆਰ ਕਰਦੇ ਹਨ, ਇਸ ਪਿਆਰ ਵਿਚ ਫਸ ਕੇ ਉਸ ਦੀ ਪ੍ਰਭੂ-ਚਰਨਾਂ ਨਾਲੋਂ) ਪ੍ਰੀਤ ਦੀ ਤਾਰ ਟੁੱਟ ਜਾਂਦੀ ਹੈ, ਮਾਇਆ ਦੀ ਤ੍ਰਿਸ਼ਨਾ ਆ ਚੰਬੜਦੀ ਹੈ, ਮਾਇਆ (ਉਸ ਉਤੇ) ਆਪਣਾ ਜ਼ੋਰ ਪਾ ਲੈਂਦੀ ਹੈ।", wordMeaning = "ਛੁੜਕੀ = ਮੁੱਕ ਗਈ, ਟੁੱਟ ਗਈ। ਅਮਰੁ = ਹੁਕਮ। ਅਮਰੁ ਵਰਤਾਇਆ = ਹੁਕਮ ਚਲਾ ਦਿੱਤਾ, ਜ਼ੋਰ ਪਾ ਲਿਆ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-152", gurmukhi = "ਏਹ ਮਾਇਆ. ਜਿਤੁ ਹਰਿ ਵਿਸਰੈ; ਮੋਹੁ ਉਪਜੈ. ਭਾਉ ਦੂਜਾ ਲਾਇਆ ॥", transliteration = "eh maaiaa. jit har visrai; moh upjai. bhaau doojaa laaiaa ||", translation = "This is Maya, by which the Lord is forgotten; emotional attachment and love of duality well up.", hindi = "एह माइआ. जितु हरि विसरै; मोहु उपजै. भाउ दूजा लाइआ ॥", punjabi = "ਮਾਇਆ ਹੈ ਹੀ ਐਸੀ ਕਿ ਇਸ ਦੀ ਰਾਹੀਂ ਰੱਬ ਭੁੱਲ ਜਾਂਦਾ ਹੈ, (ਦੁਨੀਆ ਦਾ) ਮੋਹ ਪੈਦਾ ਹੋ ਜਾਂਦਾ ਹੈ, (ਰੱਬ ਤੋਂ ਬਿਨਾ) ਹੋਰ ਹੋਰ ਪਿਆਰ ਉਪਜ ਪੈਂਦਾ ਹੈ (ਫਿਰ ਅਜੇਹੀ ਹਾਲਤ ਵਿਚ ਆਤਮਕ ਆਨੰਦ ਕਿਥੋਂ ਮਿਲੇ?)", wordMeaning = "ਜਿਤੁ = ਜਿਸ ਦੀ ਰਾਹੀਂ। ਭਾਉ ਦੂਜਾ = ਪ੍ਰਭੂ ਤੋਂ ਬਿਨਾ ਹੋਰ ਦਾ ਪਿਆਰ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-153", gurmukhi = "ਕਹੈ ਨਾਨਕੁ. ਗੁਰ ਪਰਸਾਦੀ. ਜਿਨਾ ਲਿਵ ਲਾਗੀ; ਤਿਨੀ ਵਿਚੇ ਮਾਇਆ ਪਾਇਆ ॥੨੯॥", transliteration = "kahai naanak. gur parsaadee. jinaa liv laagee; tinee viche maaiaa paaiaa ||29||", translation = "Says Nanak, by Guru's Grace, those who enshrine love for the Lord find Him, in the midst of Maya. ||29||", hindi = "कहै नानकु. गुर परसादी. जिना लिव लागी; तिनी विचे माइआ पाइआ ॥२९॥", punjabi = "ਨਾਨਕ ਆਖਦਾ ਹੈ ਕਿ ਗੁਰੂ ਦੀ ਕਿਰਪਾ ਨਾਲ ਜਿਨ੍ਹਾਂ ਬੰਦਿਆਂ ਦੀ ਪ੍ਰੀਤ ਦੀ ਡੋਰ ਪ੍ਰਭੂ-ਚਰਨਾਂ ਵਿਚ ਜੁੜੀ ਰਹਿੰਦੀ ਹੈ, ਉਹਨਾਂ ਨੂੰ ਮਾਇਆ ਵਿਚ ਵਰਤਦਿਆਂ ਹੀ (ਆਤਮਕ ਆਨੰਦ) ਮਿਲ ਪੈਂਦਾ ਹੈ ॥੨੯॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-154", gurmukhi = "ਹਰਿ ਆਪਿ ਅਮੁਲਕੁ ਹੈ; ਮੁਲਿ. ਨ ਪਾਇਆ ਜਾਇ ॥", transliteration = "har aap amulak hai; mul. na paaiaa jaai ||", translation = "The Lord Himself is priceless; His worth cannot be estimated.", hindi = "हरि आपि अमुलकु है; मुलि. न पाइआ जाइ ॥", punjabi = "(ਜਦ ਤਕ ਪਰਮਾਤਮਾ ਦਾ ਮਿਲਾਪ ਨਾ ਹੋਵੇ ਤਦ ਤਕ ਆਨੰਦ ਨਹੀਂ ਮਾਣਿਆ ਜਾ ਸਕਦਾ, ਪਰ) ਪ੍ਰਭੂ ਦਾ ਮੁੱਲ ਨਹੀਂ ਪੈ ਸਕਦਾ, ਪਰਮਾਤਮਾ (ਧਨ ਆਦਿਕ) ਕਿਸੇ ਕੀਮਤ ਤੋਂ ਨਹੀਂ ਮਿਲ ਸਕਦਾ।", wordMeaning = "ਅਮੁਲਕੁ = ਜੋ ਕਿਸੇ ਕੀਮਤ ਤੋਂ ਮਿਲ ਨ ਸਕੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-155", gurmukhi = "ਮੁਲਿ. ਨ ਪਾਇਆ ਜਾਇ. ਕਿਸੈ ਵਿਟਹੁ; ਰਹੇ ਲੋਕ ਵਿਲਲਾਇ ॥", transliteration = "mul. na paaiaa jaai. kisai vitah; rhe lok villaai ||", translation = "His worth cannot be estimated, even though people have grown weary of trying.", hindi = "मुलि. न पाइआ जाइ. किसै विटहु; रहे लोक विललाइ ॥", punjabi = "ਜੀਵ ਖਪ ਖਪ ਕੇ ਹਾਰ ਗਏ, ਕਿਸੇ ਨੂੰ (ਧਨ ਆਦਿਕ) ਕੀਮਤ ਦੇ ਕੇ ਪਰਮਾਤਮਾ ਨਹੀਂ ਮਿਲਿਆ।", wordMeaning = "ਮੁਲਿ = ਕੀਮਤ ਨਾਲ, ਕੀਮਤ ਦੇ ਕੇ। ਕਿਸੈ ਵਿਟਹੁ = ਕਿਸੇ ਭੀ ਬੰਦੇ ਤੋਂ। ਵਿਲਲਾਇ = ਖਪ ਖਪ ਕੇ। ਰਹੇ = ਰਹਿ ਗਏ, ਥੱਕ ਗਏ, ਹਾਰ ਗਏ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-156", gurmukhi = "ਐਸਾ ਸਤਿਗੁਰੁ. ਜੇ ਮਿਲੈ, ਤਿਸ ਨੋ ਸਿਰੁ ਸਉਪੀਐ; ਵਿਚਹੁ ਆਪੁ ਜਾਇ ॥", transliteration = "aisaa stigur. je milai, tis no sir saupeeai; vichah aap jaai ||", translation = "If you meet such a True Guru, offer your head to Him; your selfishness and conceit will be eradicated from within.", hindi = "ऐसा सतिगुरु. जे मिलै, तिस नो सिरु सउपीऐ; विचहु आपु जाइ ॥", punjabi = "(ਹਾਂ,) ਜੇ ਅਜੇਹਾ ਗੁਰੂ ਮਿਲ ਪਏ (ਜਿਸ ਦੇ ਮਿਲਿਆਂ ਮਨੁੱਖ ਦੇ ਅੰਦਰੋਂ ਆਪਾ-ਭਾਵ ਨਿਕਲ ਜਾਏ) ਤਾਂ ਉਸ ਗੁਰੂ ਦੇ ਅੱਗੇ ਆਪਣਾ ਸਿਰ ਭੇਟ ਕਰ ਦੇਣਾ ਚਾਹੀਦਾ ਹੈ (ਆਪਣਾ ਆਪ ਅਰਪਣ ਕਰ ਦੇਣਾ ਚਾਹੀਦਾ ਹੈ),", wordMeaning = "ਆਪੁ = ਆਪਾ-ਭਾਵ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-157", gurmukhi = "ਜਿਸ ਦਾ ਜੀਉ. ਤਿਸੁ ਮਿਲਿ ਰਹੈ; ਹਰਿ ਵਸੈ ਮਨਿ ਆਇ ॥", transliteration = "jis daa jeeu. tis mil rhai; har vsai man aai ||", translation = "Your soul belongs to Him; remain united with Him, and the Lord will come to dwell in your mind.", hindi = "जिस दा जीउ. तिसु मिलि रहै; हरि वसै मनि आइ ॥", punjabi = "(ਤੇ ਜਿਸ ਗੁਰੂ ਦੇ ਮਿਲਿਆਂ) ਜੀਵ ਉਸ ਹਰੀ ਦੇ ਚਰਨਾਂ ਵਿਚ ਜੁੜਿਆ ਰਹੇ ਉਹ ਹਰੀ ਉਸ ਦੇ ਮਨ ਵਿਚ ਵੱਸ ਪਏ ਜਿਸ ਦਾ ਇਹ ਪੈਦਾ ਕੀਤਾ ਹੋਇਆ ਹੈ।", wordMeaning = "ਜਿਸ ਦਾ = ਜਿਸ ਪਰਮਾਤਮਾ ਦਾ ਪੈਦਾ ਕੀਤਾ ਹੋਇਆ। ਜੀਉ = ਜੀਵ। ਮਨਿ = ਮਨ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-158", gurmukhi = "ਹਰਿ ਆਪਿ ਅਮੁਲਕੁ ਹੈ. ਭਾਗ ਤਿਨਾ ਕੇ ਨਾਨਕਾ; ਜਿਨ ਹਰਿ ਪਲੈ ਪਾਇ ॥੩੦॥", transliteration = "har aap amulak hai. bhaag tinaa ke naankaa; jin har plai paai ||30||", translation = "The Lord Himself is priceless; very fortunate are those, O Nanak, who attain to the Lord. ||30||", hindi = "हरि आपि अमुलकु है. भाग तिना के नानका; जिन हरि पलै पाइ ॥३०॥", punjabi = "ਹੇ ਨਾਨਕ! ਪਰਮਾਤਮਾ ਦਾ ਮੁੱਲ ਨਹੀਂ ਪੈ ਸਕਦਾ (ਕਿਸੇ ਕੀਮਤ ਤੋਂ ਨਹੀਂ ਮਿਲਦਾ, ਪਰ) ਪਰਮਾਤਮਾ ਜਿਨ੍ਹਾਂ ਨੂੰ (ਗੁਰੂ ਦੇ) ਲੜ ਲਾ ਦੇਂਦਾ ਹੈ ਉਹਨਾਂ ਦੇ ਭਾਗ ਜਾਗ ਪੈਂਦੇ ਹਨ (ਉਹ ਆਤਮਕ ਆਨੰਦ ਮਾਣਦੇ ਹਨ) ॥੩੦॥", wordMeaning = "ਪਲੈ ਪਾਇ = (ਗੁਰੂ ਦੇ) ਲੜ ਲਾ ਦੇਂਦਾ ਹੈ ॥੩੦॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-159", gurmukhi = "ਹਰਿ ਰਾਸਿ ਮੇਰੀ; ਮਨੁ ਵਣਜਾਰਾ ॥", transliteration = "har raas meree; man vanjaaraa ||", translation = "The Lord is my capital; my mind is the merchant.", hindi = "हरि रासि मेरी; मनु वणजारा ॥", punjabi = "ਪਰਮਾਤਮਾ ਦਾ ਨਾਮ ਮੇਰੀ ਰਾਸਿ-ਪੂੰਜੀ ਹੈ ਤੇ ਮੇਰਾ ਮਨ ਵਪਾਰੀ ਹੋ ਗਿਆ ਹੈ।", wordMeaning = "ਰਾਸਿ = ਵਣਜ-ਵਪਾਰ ਕਰਨ ਵਾਸਤੇ ਧਨ ਦੀ ਪੂੰਜੀ। ਵਣਜਾਰਾ = ਵਣਜ ਕਰਨ ਵਾਲਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-160", gurmukhi = "ਹਰਿ ਰਾਸਿ ਮੇਰੀ. ਮਨੁ ਵਣਜਾਰਾ; ਸਤਿਗੁਰ ਤੇ ਰਾਸਿ ਜਾਣੀ ॥", transliteration = "har raas meree. man vanjaaraa; stigur te raas jaanee ||", translation = "The Lord is my capital, and my mind is the merchant; through the True Guru, I know my capital.", hindi = "हरि रासि मेरी. मनु वणजारा; सतिगुर ते रासि जाणी ॥", punjabi = "ਆਪਣੇ ਗੁਰੂ ਤੋਂ ਮੈਨੂੰ ਸਮਝ ਆਈ ਹੈ ਕਿ (ਆਤਮਕ ਆਨੰਦ ਦੀ ਖੱਟੀ ਖੱਟਣ ਲਈ) ਪਰਮਾਤਮਾ ਦਾ ਨਾਮ ਹੀ ਮੇਰੀ ਰਾਸਿ-ਪੂੰਜੀ (ਹੋ ਸਕਦੀ ਹੈ), ਮੇਰਾ ਮਨ (ਇਸ ਵਣਜ ਦਾ) ਵਪਾਰੀ ਬਣ ਗਿਆ ਹੈ।", wordMeaning = "ਸਤਿਗੁਰ ਤੇ ਜਾਣੀ = ਗੁਰੂ ਤੋਂ ਪਛਾਣ ਪ੍ਰਾਪਤ ਕੀਤੀ।", startsAtMs = 0L, endsAtMs = 0L)
)

