    BaniLine(id = "anand-sahib-161", gurmukhi = "ਹਰਿ ਹਰਿ ਨਿਤ ਜਪਿਹੁ ਜੀਅਹੁ; ਲਾਹਾ ਖਟਿਹੁ ਦਿਹਾੜੀ ॥", transliteration = "har har nit jpih jeeah; laahaa khtih dihaaree ||", translation = "Meditate continually on the Lord, Har, Har, O my soul, and you shall collect your profits daily.", hindi = "हरि हरि नित जपिहु जीअहु; लाहा खटिहु दिहाड़ी ॥", punjabi = "ਤੁਸੀ ਭੀ ਪ੍ਰੇਮ ਨਾਲ ਸਦਾ ਹਰੀ ਦਾ ਨਾਮ ਜਪਿਆ ਕਰੋ, ਤੇ ਹਰ ਰੋਜ਼ (ਆਤਮਕ ਆਨੰਦ ਦਾ) ਲਾਭ ਖੱਟੋ।", wordMeaning = "ਜੀਅਹੁ = ਦਿਲੋਂ, ਪੂਰੇ ਪ੍ਰੇਮ ਨਾਲ। ਦਿਹਾੜੀ = ਹਰ ਰੋਜ਼।", startsAtMs = 0L, endsAtMs = 0L),
