    BaniLine(id = "anand-sahib-164", gurmukhi = "ਏ ਰਸਨਾ. ਤੂ ਅਨ ਰਸਿ ਰਾਚਿ ਰਹੀ; ਤੇਰੀ ਪਿਆਸ. ਨ ਜਾਇ ॥", transliteration = "e rasnaa. too an ras raach rhee; teree piaas. na jaai ||", translation = "O my tongue, you are engrossed in other tastes, but your thirsty desire is not quenched.", hindi = "ए रसना. तू अन रसि राचि रही; तेरी पिआस. न जाइ ॥", punjabi = "ਹੇ (ਮੇਰੀ) ਜੀਭ! ਤੂੰ ਹੋਰ ਹੋਰ ਸੁਆਦ ਵਿਚ ਮਸਤ ਹੋ ਰਹੀ ਹੈਂ, (ਇਸ ਤਰ੍ਹਾਂ) ਤੇਰਾ ਸੁਆਦਾਂ ਦਾ ਚਸਕਾ ਦੂਰ ਨਹੀਂ ਹੋ ਸਕਦਾ।", wordMeaning = "ਏ ਰਸਨਾ = ਹੇ (ਮੇਰੀ) ਜੀਭ! ਅਨ ਰਸਿ = ਹੋਰ ਹੋਰ ਰਸ ਵਿਚ। ਰਾਚਿ ਰਹੀ = ਮਸਤ ਹੋ ਰਹੀ ਹੈਂ। ਪਿਆਸ = ਸੁਆਦਾਂ ਦਾ ਚਸਕਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-165", gurmukhi = "ਪਿਆਸ. ਨ ਜਾਇ ਹੋਰਤੁ ਕਿਤੈ; ਜਿਚਰੁ ਹਰਿ ਰਸੁ ਪਲੈ. ਨ ਪਾਇ ॥", transliteration = "piaas. na jaai horat kitai; jichar har ras plai. na paai ||", translation = "Your thirst shall not be quenched by any means, until you attain the subtle essence of the Lord.", hindi = "पिआस. न जाइ होरतु कितै; जिचरु हरि रसु पलै. न पाइ ॥", punjabi = "ਜਿਤਨਾ ਚਿਰ ਪਰਮਾਤਮਾ ਦੇ ਸਿਮਰਨ ਦਾ ਆਨੰਦ ਪ੍ਰਾਪਤ ਨਾ ਹੋਵੇ, (ਉਤਨਾ ਚਿਰ) ਕਿਸੇ ਹੋਰ ਥਾਂ ਤੋਂ ਸੁਆਦਾਂ ਦਾ ਚਸਕਾ ਮਿਟ ਨਹੀਂ ਸਕਦਾ।", wordMeaning = "ਹੋਰਤੁ ਕਿਤੈ = ਕਿਸੇ ਹੋਰ ਥਾਂ ਤੋਂ। ਪਲੈ ਨ ਪਾਇ = ਨਹੀਂ ਮਿਲਦਾ।", startsAtMs = 0L, endsAtMs = 0L),
