    BaniLine(id = "anand-sahib-167", gurmukhi = "ਏਹੁ ਹਰਿ ਰਸੁ. ਕਰਮੀ ਪਾਈਐ; ਸਤਿਗੁਰੁ ਮਿਲੈ ਜਿਸੁ ਆਇ ॥", transliteration = "eh har ras. karmee paaeeai; stigur milai jis aai ||", translation = "This subtle essence of the Lord is obtained by good karma, when one comes to meet with the True Guru.", hindi = "एहु हरि रसु. करमी पाईऐ; सतिगुरु मिलै जिसु आइ ॥", punjabi = "ਪਰ ਇਹ ਹਰੀ-ਨਾਮ ਦਾ ਆਨੰਦ ਪ੍ਰਭੂ ਦੀ ਮੇਹਰ ਨਾਲ ਮਿਲਦਾ ਹੈ (ਉਸ ਨੂੰ ਮਿਲਦਾ ਹੈ) ਜਿਸ ਨੂੰ ਗੁਰੂ ਮਿਲੇ।", wordMeaning = "ਕਰਮੀ = ਪ੍ਰਭੂ ਦੀ ਮੇਹਰ ਨਾਲ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-168", gurmukhi = "ਕਹੈ ਨਾਨਕੁ. ਹੋਰਿ ਅਨ ਰਸ ਸਭਿ ਵੀਸਰੇ; ਜਾ ਹਰਿ ਵਸੈ ਮਨਿ ਆਇ ॥੩੨॥", transliteration = "kahai naanak. hor an ras sabh veesre; jaa har vsai man aai ||32||", translation = "Says Nanak, all other tastes and essences are forgotten, when the Lord comes to dwell within the mind. ||32||", hindi = "कहै नानकु. होरि अन रस सभि वीसरे; जा हरि वसै मनि आइ ॥३२॥", punjabi = "ਨਾਨਕ ਆਖਦਾ ਹੈ ਕਿ ਜਦੋਂ ਹਰੀ-ਸਿਮਰਨ ਦਾ ਆਨੰਦ ਮਨ ਵਿਚ ਵੱਸ ਪਏ, ਤਦੋਂ ਹੋਰ ਹੋਰ ਸਾਰੇ ਚਸਕੇ ਭੁੱਲ ਜਾਂਦੇ ਹਨ ॥੩੨॥", wordMeaning = "ਹੋਰਿ ਅਨ ਰਸ = ਹੋਰ ਦੂਜੇ ਸਾਰੇ ਸੁਆਦ। ਸਭਿ = ਸਾਰੇ। ਮਨ = ਮਨ ਵਿਚ ॥੩੨॥", startsAtMs = 0L, endsAtMs = 0L),
