    BaniLine(id = "anand-sahib-170", gurmukhi = "ਹਰਿ ਜੋਤਿ ਰਖੀ. ਤੁਧੁ ਵਿਚਿ; ਤਾ ਤੂ ਜਗ ਮਹਿ ਆਇਆ ॥", transliteration = "har jot rkhee. tudh vich; taa too jag mah aaiaa ||", translation = "The Lord infused His Light into you, and then you came into the world.", hindi = "हरि जोति रखी. तुधु विचि; ता तू जग महि आइआ ॥", punjabi = "(ਇਹ ਯਕੀਨ ਜਾਣ ਕਿ) ਜਦੋਂ ਪਰਮਾਤਮਾ ਨੇ ਤੇਰੇ ਅੰਦਰ ਆਪਣੀ ਜੋਤਿ ਰੱਖੀ, ਤਦੋਂ ਤੂੰ ਜਗਤ ਵਿਚ ਜੰਮਿਆ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
