    BaniLine(id = "anand-sahib-172", gurmukhi = "ਗੁਰ ਪਰਸਾਦੀ ਬੁਝਿਆ. ਤਾ ਚਲਤੁ ਹੋਆ; ਚਲਤੁ ਨਦਰੀ ਆਇਆ ॥", transliteration = "gur parsaadee bujhiaa. taa chalat hoaa; chalat nadree aaiaa ||", translation = "By Guru's Grace, some understand, and then it's a show; it seems like just a show.", hindi = "गुर परसादी बुझिआ. ता चलतु होआ; चलतु नदरी आइआ ॥", punjabi = "ਜਦੋਂ ਗੁਰੂ ਦੀ ਮੇਹਰ ਨਾਲ ਜੀਵ ਨੂੰ ਗਿਆਨ ਹੁੰਦਾ ਹੈ ਤਾਂ ਇਸ ਨੂੰ ਸਮਝ ਆਉਂਦੀ ਹੈ ਕਿ ਇਹ ਜਗਤ ਤਾਂ ਇਕ ਖੇਡ ਹੀ ਹੈ, ਫਿਰ ਜੀਵ ਨੂੰ ਇਹ ਜਗਤ (ਮਦਾਰੀ ਦਾ) ਇਕ ਤਮਾਸ਼ਾ ਹੀ ਦਿੱਸ ਪੈਂਦਾ ਹੈ (ਸਦਾ-ਥਿਰ ਰਹਿਣ ਵਾਲਾ ਆਤਮਕ ਆਨੰਦ ਇਸ ਵਿਚ ਨਹੀਂ ਹੋ ਸਕਦਾ)।", wordMeaning = "ਚਲਤੁ = ਖੇਡ, ਤਮਾਸ਼ਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-173", gurmukhi = "ਕਹੈ ਨਾਨਕੁ. ਸ੍ਰਿਸਟਿ ਕਾ ਮੂਲੁ ਰਚਿਆ. ਜੋਤਿ ਰਾਖੀ; ਤਾ ਤੂ ਜਗ ਮਹਿ ਆਇਆ ॥੩੩॥", transliteration = "kahai naanak. srisat kaa mool rchiaa. jot raakhee; taa too jag mah aaiaa ||33||", translation = "Says Nanak, He laid the foundation of the Universe, and infused His Light, and then you came into the world. ||33||", hindi = "कहै नानकु. स्रिसटि का मूलु रचिआ. जोति राखी; ता तू जग महि आइआ ॥३३॥", punjabi = "ਨਾਨਕ ਆਖਦਾ ਹੈ ਕਿ ਹੇ ਮੇਰੇ ਸਰੀਰ! ਜਦੋਂ ਪ੍ਰਭੂ ਨੇ ਜਗਤ-ਰਚਨਾ ਦਾ ਮੁੱਢ ਬੱਧਾ, ਤੇਰੇ ਅੰਦਰ ਆਪਣੀ ਜੋਤਿ ਪਾਈ, ਤਦੋਂ ਤੂੰ ਜਗਤ ਵਿਚ ਜਨਮਿਆ ॥੩੩॥", wordMeaning = "ਮੂਲੁ ਰਚਿਆ = ਮੁੱਢ ਬੱਧਾ। ਜਿਨਿ = ਜਿਸ (ਪਰਮਾਤਮਾ) ਨੇ ॥੩੩॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-174", gurmukhi = "ਮਨਿ ਚਾਉ ਭਇਆ; ਪ੍ਰਭ ਆਗਮੁ ਸੁਣਿਆ ॥", transliteration = "man chaau bhaiaa; prabh aagam suniaa ||", translation = "My mind has become joyful, hearing of God's coming.", hindi = "मनि चाउ भइआ; प्रभ आगमु सुणिआ ॥", punjabi = "ਆਪਣੀ ਹਿਰਦੇ-ਸੇਜ ਉਤੇ ਪ੍ਰਭੂ-ਪਤੀ ਦਾ ਆਉਣਾ ਮੈਂ ਸੁਣ ਲਿਆ ਹੈ (ਮੈਂ ਅਨੁਭਵ ਕਰ ਲਿਆ ਹੈ ਕਿ ਪ੍ਰਭੂ ਮੇਰੇ ਹਿਰਦੇ ਵਿਚ ਆ ਵੱਸਿਆ ਹੈ ਹੁਣ) ਮੇਰੇ ਮਨ ਵਿਚ ਆਨੰਦ ਬਣ ਗਿਆ ਹੈ।", wordMeaning = "ਚਾਉ = ਆਨੰਦ। ਪ੍ਰਭ ਆਗਮੁ = ਪ੍ਰਭੂ ਦਾ ਆਉਣਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-175", gurmukhi = "ਹਰਿ ਮੰਗਲੁ ਗਾਉ ਸਖੀ; ਗ੍ਰਿਹੁ ਮੰਦਰੁ ਬਣਿਆ ॥", transliteration = "har mangal gaau skhee; grih mandar bniaa ||", translation = "Sing the songs of joy to welcome the Lord, O my companions; my household has become the Lord's Mansion.", hindi = "हरि मंगलु गाउ सखी; ग्रिहु मंदरु बणिआ ॥", punjabi = "ਹੇ ਮੇਰੀ ਜਿੰਦੇ! ਮੇਰਾ ਇਹ ਹਿਰਦਾ-ਘਰ ਪ੍ਰਭੂ-ਪਤੀ ਦਾ ਨਿਵਾਸ-ਅਸਥਾਨ ਬਣ ਗਿਆ ਹੈ, ਹੁਣ ਤੂੰ ਪ੍ਰਭੂ ਦੀ ਸਿਫ਼ਤ-ਸਾਲਾਹ ਦਾ ਗੀਤ ਗਾ।", wordMeaning = "ਸਖੀ = ਹੇ ਸਖੀ! ਹੇ ਜਿੰਦੇ! ਮੰਗਲੁ = ਖ਼ੁਸ਼ੀ ਦਾ ਗੀਤ, ਪ੍ਰਭੂ ਦੀ ਸਿਫ਼ਤ-ਸਾਲਾਹ ਦਾ ਗੀਤ। ਗ੍ਰਿਹੁ = ਹਿਰਦਾ-ਘਰ। ਮੰਦਰੁ = ਪ੍ਰਭੂ ਦਾ ਨਿਵਾਸ-ਅਸਥਾਨ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-176", gurmukhi = "ਹਰਿ ਗਾਉ ਮੰਗਲੁ ਨਿਤ ਸਖੀਏ; ਸੋਗੁ ਦੂਖੁ. ਨ ਵਿਆਪਏ ॥", transliteration = "har gaau mangal nit skheee; sog dookh. na viaapae ||", translation = "Sing continually the songs of joy to welcome the Lord, O my companions, and sorrow and suffering will not afflict you.", hindi = "हरि गाउ मंगलु नित सखीए; सोगु दूखु. न विआपए ॥", punjabi = "ਹੇ ਜਿੰਦੇ! ਸਦਾ ਪ੍ਰਭੂ ਦੀ ਵਡਿਆਈ ਦਾ ਗੀਤ ਗਾਂਦੀ ਰਹੁ, (ਇਹ ਤਰ੍ਹਾਂ) ਕੋਈ ਫ਼ਿਕਰ ਕੋਈ ਦੁੱਖ (ਆਪਣਾ) ਜ਼ੋਰ ਨਹੀਂ ਪਾ ਸਕਦਾ।", wordMeaning = "ਨ ਵਿਆਪਏ = ਨਹੀਂ ਵਿਆਪਦਾ, ਆਪਣਾ ਦਬਾਉ ਨਹੀਂ ਪਾਂਦਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-177", gurmukhi = "ਗੁਰ ਚਰਨ ਲਾਗੇ. ਦਿਨ ਸਭਾਗੇ; ਆਪਣਾ ਪਿਰੁ ਜਾਪਏ ॥", transliteration = "gur charan laage. din sbhaage; aapnaa pir jaapae ||", translation = "Blessed is that day, when I am attached to the Guru's feet and meditate on my Husband Lord.", hindi = "गुर चरन लागे. दिन सभागे; आपणा पिरु जापए ॥", punjabi = "ਉਹ ਦਿਨ ਭਾਗਾਂ ਵਾਲੇ ਹੁੰਦੇ ਹਨ ਜਦੋਂ (ਮੱਥਾ) ਗੁਰੂ ਦੇ ਚਰਨਾਂ ਉਤੇ ਟਿਕੇ, ਪਿਆਰਾ ਪਤੀ-ਪ੍ਰਭੂ (ਹਿਰਦੇ ਵਿਚ) ਦਿੱਸ ਪੈਂਦਾ ਹੈ।", wordMeaning = "ਸਭਾਗੇ = ਭਾਗਾਂ ਵਾਲੇ। ਜਾਪਏ = ਦਿੱਸ ਪਿਆ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-178", gurmukhi = "ਅਨਹਤ ਬਾਣੀ. ਗੁਰ ਸਬਦਿ ਜਾਣੀ; ਹਰਿ ਨਾਮੁ ਹਰਿ ਰਸੁ ਭੋਗੋ ॥", transliteration = "anahat baanee. gur sabad jaanee; har naam har ras bhogo ||", translation = "I have come to know the unstruck sound current and the Word of the Guru's Shabad; I enjoy the sublime essence of the Lord, the Lord's Name.", hindi = "अनहत बाणी. गुर सबदि जाणी; हरि नामु हरि रसु भोगो ॥", punjabi = "ਗੁਰੂ ਦੇ ਸ਼ਬਦ ਦੀ ਰਾਹੀਂ ਇਕ-ਰਸ ਸਿਫ਼ਤ-ਸਾਲਾਹ ਦੀ ਰੌ ਨਾਲ ਸਾਂਝ ਬਣ ਜਾਂਦੀ ਹੈ, ਪ੍ਰਭੂ ਦਾ ਨਾਮ ਪ੍ਰਾਪਤ ਹੋ ਜਾਂਦਾ ਹੈ, ਪ੍ਰਭੂ-ਮਿਲਾਪ ਦਾ ਆਨੰਦ ਮਾਣੀਦਾ ਹੈ।", wordMeaning = "ਅਨਹਤ = ਇਕ-ਰਸ। ਅਨਹਤ ਬਾਣੀ = ਇਕ-ਰਸ ਸਿਫ਼ਤ-ਸਾਲਾਹ ਦੀ ਰੌ। ਸਬਦਿ = ਸ਼ਬਦ ਦੀ ਰਾਹੀਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-179", gurmukhi = "ਕਹੈ ਨਾਨਕੁ. ਪ੍ਰਭੁ ਆਪਿ ਮਿਲਿਆ; ਕਰਣ ਕਾਰਣ ਜੋਗੋ ॥੩੪॥", transliteration = "kahai naanak. prabh aap miliaa; karan kaaran jogo ||34||", translation = "Says Nanak, God Himself has met me; He is the Doer, the Cause of causes. ||34||", hindi = "कहै नानकु. प्रभु आपि मिलिआ; करण कारण जोगो ॥३४॥", punjabi = "ਨਾਨਕ ਆਖਦਾ ਹੈ ਕਿ (ਹੇ ਜਿੰਦੇ! ਖ਼ੁਸ਼ੀ ਦਾ ਗੀਤ ਗਾ) ਸਭ ਕੁਝ ਕਰਨ ਦੇ ਸਮਰੱਥ ਪ੍ਰਭੂ ਆਪ ਆ ਕੇ ਮੈਨੂੰ ਮਿਲ ਪਿਆ ਹੈ ॥੩੪॥", wordMeaning = "ਜੋਗੋ = ਸਮਰੱਥ ॥੩੪॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-180", gurmukhi = "ਏ ਸਰੀਰਾ ਮੇਰਿਆ. ਇਸੁ ਜਗ ਮਹਿ ਆਇ ਕੈ; ਕਿਆ ਤੁਧੁ ਕਰਮ ਕਮਾਇਆ ॥", transliteration = "e sreeraa meriaa. is jag mah aai kai; kiaa tudh karam kmaaiaa ||", translation = "O my body, why have you come into this world? What actions have you committed?", hindi = "ए सरीरा मेरिआ. इसु जग महि आइ कै; किआ तुधु करम कमाइआ ॥", punjabi = "ਹੇ ਮੇਰੇ ਸਰੀਰ! ਇਸ ਜਗਤ ਵਿਚ ਜਨਮ ਲੈ ਕੇ ਤੂੰ ਹੋਰ ਹੋਰ ਕੰਮ ਹੀ ਕਰਦਾ ਰਿਹਾ।", wordMeaning = "ਕਿਆ ਕਰਮ = ਕੇਹੜੇ ਕੰਮ? ਹੋਰ ਹੋਰ ਕੰਮ ਹੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-181", gurmukhi = "ਕਿ ਕਰਮ ਕਮਾਇਆ. ਤੁਧੁ ਸਰੀਰਾ; ਜਾ ਤੂ. ਜਗ ਮਹਿ ਆਇਆ ॥", transliteration = "ki karam kmaaiaa. tudh sreeraa; jaa too. jag mah aaiaa ||", translation = "And what actions have you committed, O my body, since you came into this world?", hindi = "कि करम कमाइआ. तुधु सरीरा; जा तू. जग महि आइआ ॥", punjabi = "ਜਦੋਂ ਦਾ ਤੂੰ ਸੰਸਾਰ ਵਿਚ ਆਇਆ ਹੈਂ, ਤੂੰ (ਪ੍ਰਭੂ-ਸਿਮਰਨ ਤੋਂ ਬਿਨਾ) ਹੋਰ ਹੋਰ ਕੰਮ ਹੀ ਕਰਦਾ ਰਿਹਾ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-182", gurmukhi = "ਜਿਨਿ ਹਰਿ ਤੇਰਾ ਰਚਨੁ ਰਚਿਆ; ਸੋ ਹਰਿ ਮਨਿ. ਨ ਵਸਾਇਆ ॥", transliteration = "jin har teraa rachan rchiaa; so har man. na vsaaiaa ||", translation = "The Lord who formed your form - you have not enshrined that Lord in your mind.", hindi = "जिनि हरि तेरा रचनु रचिआ; सो हरि मनि. न वसाइआ ॥", punjabi = "ਜਿਸ ਹਰੀ ਨੇ ਤੈਨੂੰ ਪੈਦਾ ਕੀਤਾ ਹੈ, ਉਸ ਨੂੰ ਤੂੰ ਆਪਣੇ ਮਨ ਵਿਚ ਨਹੀਂ ਵਸਾਇਆ (ਉਸ ਦੀ ਯਾਦ ਵਿਚ ਕਦੇ ਨਹੀਂ ਜੁੜਿਆ)।", wordMeaning = "ਜਿਨਿ ਹਰਿ = ਜਿਸ ਹਰੀ ਨੇ। ਤੇਰਾ ਰਚਨੁ ਰਚਿਆ = ਤੈਨੂੰ ਪੈਦਾ ਕੀਤਾ। ਮਨਿ = ਮਨ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-183", gurmukhi = "ਗੁਰ ਪਰਸਾਦੀ ਹਰਿ ਮੰਨਿ ਵਸਿਆ; ਪੂਰਬਿ ਲਿਖਿਆ ਪਾਇਆ ॥", transliteration = "gur parsaadee har mann vsiaa; poorab likhiaa paaiaa ||", translation = "By Guru's Grace, the Lord abides within the mind, and one's pre-ordained destiny is fulfilled.", hindi = "गुर परसादी हरि मंनि वसिआ; पूरबि लिखिआ पाइआ ॥", punjabi = "(ਪਰ, ਹੇ ਸਰੀਰ! ਤੇਰੇ ਭੀ ਕੀਹ ਵੱਸ?) ਜਿਸ ਮਨੁੱਖ ਦੇ ਪੂਰਬਲੇ ਕੀਤੇ ਕਰਮਾਂ ਦੇ ਸੰਸਕਾਰ ਉੱਘੜਦੇ ਹਨ, ਗੁਰੂ ਦੀ ਕਿਰਪਾ ਨਾਲ ਉਸ ਦੇ ਮਨ ਵਿਚ ਪਰਮਾਤਮਾ ਵੱਸਦਾ ਹੈ (ਉਹੀ ਹਰੀ-ਸਿਮਰਨ ਵਿਚ ਜੁੜਦਾ ਹੈ)।", wordMeaning = "ਮੰਨਿ = ਮਨ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-184", gurmukhi = "ਕਹੈ ਨਾਨਕੁ. ਏਹੁ ਸਰੀਰੁ ਪਰਵਾਣੁ ਹੋਆ; ਜਿਨਿ ਸਤਿਗੁਰ ਸਿਉ ਚਿਤੁ ਲਾਇਆ ॥੩੫॥", transliteration = "kahai naanak. eh sreer parvaan hoaa; jin stigur siu chit laaiaa ||35||", translation = "Says Nanak, this body is adorned and honored, when one's consciousness is focused on the True Guru. ||35||", hindi = "कहै नानकु. एहु सरीरु परवाणु होआ; जिनि सतिगुर सिउ चितु लाइआ ॥३५॥", punjabi = "ਨਾਨਕ ਆਖਦਾ ਹੈ ਕਿ ਜਿਸ ਮਨੁੱਖ ਨੇ ਗੁਰੂ-ਚਰਨਾਂ ਵਿਚ ਚਿੱਤ ਜੋੜ ਲਿਆ, (ਉਸ ਦਾ) ਇਹ ਸਰੀਰ ਸਫਲ ਹੋ ਜਾਂਦਾ ਹੈ (ਉਹ ਮਨੁੱਖ ਉਹ ਮਨੋਰਥ ਪੂਰਾ ਕਰ ਲੈਂਦਾ ਹੈ ਜਿਸ ਵਾਸਤੇ ਇਹ ਬਣਾਇਆ ਗਿਆ) ॥੩੫॥", wordMeaning = "ਜਿਨਿ = ਜਿਸ ਮਨੁੱਖ ਨੇ। ਪਰਵਾਣੁ = ਕਬੂਲ, ਸਫਲ ॥੩੫॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-185", gurmukhi = "ਏ ਨੇਤ੍ਰਹੁ ਮੇਰਿਹੋ. ਹਰਿ ਤੁਮ ਮਹਿ ਜੋਤਿ ਧਰੀ; ਹਰਿ ਬਿਨੁ ਅਵਰੁ. ਨ ਦੇਖਹੁ ਕੋਈ ॥", transliteration = "e netrah meriho. har tum mah jot dhree; har bin avar. na dekhah koee ||", translation = "O my eyes, the Lord has infused His Light into you; do not look upon any other than the Lord.", hindi = "ए नेत्रहु मेरिहो. हरि तुम महि जोति धरी; हरि बिनु अवरु. न देखहु कोई ॥", punjabi = "ਹੇ ਮੇਰੀਓ ਅੱਖੀਓ! ਪਰਮਾਤਮਾ ਨੇ ਤੁਹਾਡੇ ਅੰਦਰ (ਆਪਣੀ) ਜੋਤਿ ਟਿਕਾਈ ਹੈ (ਤਾਹੀਏਂ ਤੁਸੀ ਵੇਖਣ-ਜੋਗੀਆਂ ਹੋ) ਜਿੱਧਰ ਤੱਕੋ, ਪਰਮਾਤਮਾ ਦਾ ਹੀ ਦੀਦਾਰ ਕਰੋ।", wordMeaning = "ਨੇਤ੍ਰ = ਅੱਖਾਂ। ਜੋਤਿ = ਰੋਸ਼ਨੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-186", gurmukhi = "ਹਰਿ ਬਿਨੁ ਅਵਰੁ. ਨ ਦੇਖਹੁ ਕੋਈ; ਨਦਰੀ ਹਰਿ ਨਿਹਾਲਿਆ ॥", transliteration = "har bin avar. na dekhah koee; nadree har nihaaliaa ||", translation = "Do not look upon any other than the Lord; the Lord alone is worthy of beholding.", hindi = "हरि बिनु अवरु. न देखहु कोई; नदरी हरि निहालिआ ॥", punjabi = "ਪਰਮਾਤਮਾ ਤੋਂ ਬਿਨਾ ਹੋਰ ਕੋਈ ਗ਼ੈਰ ਨਾ ਦਿੱਸੇ, ਨਿਗਾਹ ਨਾਲ ਹਰੀ ਨੂੰ ਵੇਖੋ।", wordMeaning = "ਨਿਹਾਲਿਆ = ਨਿਹਾਲੋ, ਵੇਖੋ। ਨਦਰੀ = ਨਜ਼ਰ ਨਾਲ, ਅੱਖਾਂ ਨਾਲ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-187", gurmukhi = "ਏਹੁ ਵਿਸੁ ਸੰਸਾਰੁ. ਤੁਮ ਦੇਖਦੇ. ਏਹੁ ਹਰਿ ਕਾ ਰੂਪੁ ਹੈ; ਹਰਿ ਰੂਪੁ ਨਦਰੀ ਆਇਆ ॥", transliteration = "eh vis sansaar. tum dekhde. eh har kaa roop hai; har roop nadree aaiaa ||", translation = "This whole world which you see is the image of the Lord; only the image of the Lord is seen.", hindi = "एहु विसु संसारु. तुम देखदे. एहु हरि का रूपु है; हरि रूपु नदरी आइआ ॥", punjabi = "(ਹੇ ਅੱਖੀਓ!) ਇਹ ਸਾਰਾ ਸੰਸਾਰ ਜੋ ਤੁਸੀ ਵੇਖ ਰਹੀਆਂ ਹੋ, ਇਹ ਪ੍ਰਭੂ ਦਾ ਹੀ ਰੂਪ ਹੈ, ਪ੍ਰਭੂ ਦਾ ਹੀ ਰੂਪ ਦਿੱਸ ਰਿਹਾ ਹੈ।", wordMeaning = "ਵਿਸੁ = ਵਿਸ਼੍ਵ, ਸਾਰਾ। ਨਦਰੀ ਆਇਆ = ਦਿੱਸਦਾ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-188", gurmukhi = "ਗੁਰ ਪਰਸਾਦੀ ਬੁਝਿਆ. ਜਾ ਵੇਖਾ ਹਰਿ ਇਕੁ ਹੈ; ਹਰਿ ਬਿਨੁ ਅਵਰੁ. ਨ ਕੋਈ ॥", transliteration = "gur parsaadee bujhiaa. jaa vekhaa har ik hai; har bin avar. na koee ||", translation = "By Guru's Grace, I understand, and I see only the One Lord; there is no one except the Lord.", hindi = "गुर परसादी बुझिआ. जा वेखा हरि इकु है; हरि बिनु अवरु. न कोई ॥", punjabi = "ਗੁਰੂ ਦੀ ਕਿਰਪਾ ਨਾਲ ਮੈਨੂੰ ਸਮਝ ਪਈ ਹੈ, ਹੁਣ ਮੈਂ ਜਦੋਂ (ਚੁਫੇਰੇ) ਵੇਖਦਾ ਹਾਂ, ਹਰ ਥਾਂ ਇਕ ਪਰਮਾਤਮਾ ਹੀ ਦਿੱਸਦਾ ਹੈ, ਉਸ ਤੋਂ ਬਿਨਾ ਹੋਰ ਕੁਝ ਨਹੀਂ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
