    BaniLine(id = "anand-sahib-199", gurmukhi = "ਕਹੈ ਨਾਨਕੁ. ਹਰਿ ਪਿਆਰੈ ਜੀਉ. ਗੁਫਾ ਅੰਦਰਿ ਰਖਿ ਕੈ; ਵਾਜਾ ਪਵਣੁ ਵਜਾਇਆ ॥੩੮॥", transliteration = "kahai naanak. har piaarai jeeu. guphaa andar rakh kai; vaajaa pavan vjaaiaa ||38||", translation = "Says Nanak, the Lord placed the soul to the cave of the body, and blew the breath of life into the musical instrument of the body. ||38||", hindi = "कहै नानकु. हरि पिआरै जीउ. गुफा अंदरि रखि कै; वाजा पवणु वजाइआ ॥३८॥", punjabi = "ਨਾਨਕ ਆਖਦਾ ਹੈ ਕਿ ਪਿਆਰੇ ਪ੍ਰਭੂ ਨੇ ਜਿੰਦ ਨੂੰ ਸਰੀਰ-ਗੁਫ਼ਾ ਵਿਚ ਟਿਕਾ ਕੇ ਜੀਵ ਨੂੰ ਬੋਲਣ ਦੀ ਸ਼ਕਤੀ ਭੀ ਦਿੱਤੀ ॥੩੮॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-200", gurmukhi = "ਏਹੁ ਸਾਚਾ ਸੋਹਿਲਾ; ਸਾਚੈ ਘਰਿ ਗਾਵਹੁ ॥", transliteration = "eh saachaa sohilaa; saachai ghar gaavah ||", translation = "Sing this true song of praise in the true home of your soul.", hindi = "एहु साचा सोहिला; साचै घरि गावहु ॥", punjabi = "ਪਰਮਾਤਮਾ ਦੀ ਸਿਫ਼ਤ-ਸਾਲਾਹ ਦੀ ਇਹ ਬਾਣੀ ਸਾਧ ਸੰਗਤ ਵਿਚ (ਬੈਠ ਕੇ) ਗਾਵਿਆ ਕਰੋ।", wordMeaning = "ਸੋਹਿਲਾ = ਖ਼ੁਸ਼ੀ ਦਾ ਗੀਤ, ਆਤਮਕ ਆਨੰਦ ਪੈਦਾ ਕਰਨ ਵਾਲਾ ਗੀਤ, ਪ੍ਰਭੂ ਦੀ ਸਿਫ਼ਤ-ਸਾਲਾਹ ਦੀ ਬਾਣੀ। ਸਾਚੈ ਘਰਿ = ਸਦਾ-ਥਿਰ ਰਹਿਣ ਵਾਲੇ ਘਰ ਵਿਚ, ਸਾਧ ਸੰਗਤ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-201", gurmukhi = "ਗਾਵਹੁ ਤ ਸੋਹਿਲਾ ਘਰਿ ਸਾਚੈ; ਜਿਥੈ ਸਦਾ ਸਚੁ ਧਿਆਵਹੇ ॥", transliteration = "gaavah ta sohilaa ghar saachai; jithai sdaa sach dhiaavhe ||", translation = "Sing the song of praise in your true home; meditate there on the True Lord forever.", hindi = "गावहु त सोहिला घरि साचै; जिथै सदा सचु धिआवहे ॥", punjabi = "ਉਸ ਸਤ ਸੰਗ ਵਿਚ ਆਮਤਕ ਅਨੰਦ ਦੇਣ ਵਾਲੀ ਬਾਣੀ ਗਾਵਿਆ ਕਰੋ, ਜਿਥੇ (ਗੁਰਮੁਖਿ ਜਨ) ਸਦਾ-ਥਿਰ ਰਹਿਣ ਵਾਲੇ ਪ੍ਰਭੂ ਨੂੰ ਸਦਾ ਗਾਂਦੇ ਹਨ।", wordMeaning = "ਸਚੁ = ਸਦਾ-ਥਿਰ ਪ੍ਰਭੂ। ਗਾਵਹੁ = ਗਾਵਹਿ, (ਸਤ ਸੰਗੀ) ਗਾਂਦੇ ਹਨ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-202", gurmukhi = "ਸਚੋ ਧਿਆਵਹਿ ਜਾ ਤੁਧੁ ਭਾਵਹਿ; ਗੁਰਮੁਖਿ ਜਿਨਾ ਬੁਝਾਵਹੇ ॥", transliteration = "sacho dhiaavah jaa tudh bhaavah; gurmukh jinaa bujhaavhe ||", translation = "They alone meditate on You, O True Lord, who are pleasing to Your Will; as Gurmukh, they understand.", hindi = "सचो धिआवहि जा तुधु भावहि; गुरमुखि जिना बुझावहे ॥", punjabi = "ਹੇ ਪ੍ਰਭੂ! ਤੈਨੂੰ ਸਦਾ-ਥਿਰ ਨੂੰ ਤਦੋਂ ਹੀ ਜੀਵ ਸਿਮਰਦੇ ਹਨ ਜਦੋਂ ਤੈਨੂੰ ਚੰਗੇ ਲੱਗਣ, ਜਿਨ੍ਹਾਂ ਨੂੰ ਤੂੰ ਗੁਰੂ ਦੀ ਰਾਹੀਂ ਇਹ ਸੂਝ ਬਖ਼ਸ਼ੇਂ।", wordMeaning = "ਭਾਵਹਿ = ਜੇ ਤੈਨੂੰ ਚੰਗੇ ਲੱਗਣ, ਹੇ ਪ੍ਰਭੂ! ਬੁਝਾਵਹੇ = ਤੂੰ ਸੂਝ ਬਖ਼ਸ਼ੇਂ। ਗੁਰਮੁਖਿ = ਗੁਰੂ ਦੀ ਰਾਹੀਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-203", gurmukhi = "ਇਹੁ ਸਚੁ ਸਭਨਾ ਕਾ ਖਸਮੁ ਹੈ; ਜਿਸੁ ਬਖਸੇ. ਸੋ ਜਨੁ ਪਾਵਹੇ ॥", transliteration = "ih sach sabhnaa kaa khasam hai; jis bakhse. so jan paavhe ||", translation = "This Truth is the Lord and Master of all; whoever is blessed, obtains it.", hindi = "इहु सचु सभना का खसमु है; जिसु बखसे. सो जनु पावहे ॥", punjabi = "ਸਦਾ-ਥਿਰ ਪ੍ਰਭੂ ਸਭ ਜੀਵਾਂ ਦਾ ਮਾਲਕ ਹੈ, ਜਿਸ ਜਿਸ ਉਤੇ ਉਹ ਮੇਹਰ ਕਰਦਾ ਹੈ ਉਹ ਉਹ ਜੀਵ ਤੈਨੂੰ ਪ੍ਰਾਪਤ ਕਰ ਲੈਂਦੇ ਹਨ।", wordMeaning = "ਪਾਵਹੇ = ਪ੍ਰਾਪਤ ਕਰਦੇ ਹਨ, ਪਾਵਹਿ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-204", gurmukhi = "ਕਹੈ ਨਾਨਕੁ. ਸਚੁ ਸੋਹਿਲਾ; ਸਚੈ ਘਰਿ ਗਾਵਹੇ ॥੩੯॥", transliteration = "kahai naanak. sach sohilaa; schai ghar gaavhe ||39||", translation = "Says Nanak, sing the true song of praise in the true home of your soul. ||39||", hindi = "कहै नानकु. सचु सोहिला; सचै घरि गावहे ॥३९॥", punjabi = "ਤੇ, ਨਾਨਕ ਆਖਦਾ ਹੈ, ਉਹ ਸਤ ਸੰਗਤ ਵਿਚ (ਬੈਠ ਕੇ) ਪ੍ਰਭੂ ਦੀ ਸਿਫ਼ਤ-ਸਾਲਾਹ ਵਾਲੀ ਬਾਣੀ ਗਾਂਦੇ ਹਨ ॥੩੯॥", wordMeaning = "ਗਾਵਹੇ = ਗਾਵਹਿ, ਗਾਂਦੇ ਹਨ ॥੩੯॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-205", gurmukhi = "ਅਨਦੁ ਸੁਣਹੁ ਵਡਭਾਗੀਹੋ; ਸਗਲ ਮਨੋਰਥ ਪੂਰੇ ॥", transliteration = "anad sunah vadbhaageeho; sagal mnorath poore ||", translation = "Listen to the song of bliss, O most fortunate ones; all your longings shall be fulfilled.", hindi = "अनदु सुणहु वडभागीहो; सगल मनोरथ पूरे ॥", punjabi = "ਹੇ ਵੱਡੇ ਭਾਗਾਂ ਵਾਲਿਓ! ਸੁਣੋ, ਆਨੰਦ ਇਹ ਹੈ ਕਿ (ਉਸ ਅਵਸਥਾ ਵਿਚ) ਮਨ ਦੀਆਂ ਸਾਰੀਆਂ ਦੌੜਾਂ ਮੁੱਕ ਜਾਂਦੀਆਂ ਹਨ (ਸਾਰੇ ਸੰਕਲਪ ਸਿਰੇ ਚੜ੍ਹ ਜਾਂਦੇ ਹਨ),", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-206", gurmukhi = "ਪਾਰਬ੍ਰਹਮੁ ਪ੍ਰਭੁ ਪਾਇਆ; ਉਤਰੇ ਸਗਲ ਵਿਸੂਰੇ ॥", transliteration = "paarabraham prabh paaiaa; utre sagal visoore ||", translation = "I have obtained the Supreme Lord God, and all sorrows have been forgotten.", hindi = "पारब्रहमु प्रभु पाइआ; उतरे सगल विसूरे ॥", punjabi = "ਪਰਮ ਆਤਮਾ ਪ੍ਰਭੂ ਮਿਲ ਪੈਂਦਾ ਹੈ, ਸਾਰੇ ਚਿੰਤਾ-ਝੌਰੇ ਮਨ ਤੋਂ ਲਹਿ ਜਾਂਦੇ ਹਨ।", wordMeaning = "ਵਿਸੂਰੇ = ਚਿੰਤਾ-ਝੋਰੇ। ਸੰਤਾਪ = ਕਲੇਸ਼।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-207", gurmukhi = "ਦੂਖ ਰੋਗ ਸੰਤਾਪ ਉਤਰੇ; ਸੁਣੀ ਸਚੀ ਬਾਣੀ ॥", transliteration = "dookh rog santaap utre; sunee schee baanee ||", translation = "Pain, illness and suffering have departed, listening to the True Bani.", hindi = "दूख रोग संताप उतरे; सुणी सची बाणी ॥", punjabi = "ਅਕਾਲ ਪੁਰਖ ਦੀ ਸਿਫ਼ਤ-ਸਾਲਾਹ ਦੀ ਬਾਣੀ ਸੁਣਿਆਂ ਸਾਰੇ ਦੁੱਖ ਰੋਗ ਕਲੇਸ਼ ਮਿਟ ਜਾਂਦੇ ਹਨ।", wordMeaning = "ਸਚੀ ਬਾਣੀ = ਸਦਾ-ਥਿਰ ਪ੍ਰਭੂ ਦੀ ਸਿਫ਼ਤ-ਸਾਲਾਹ ਦੀ ਬਾਣੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-208", gurmukhi = "ਸੰਤ ਸਾਜਨ ਭਏ ਸਰਸੇ; ਪੂਰੇ ਗੁਰ ਤੇ ਜਾਣੀ ॥", transliteration = "sant saajan bhae sarse; poore gur te jaanee ||", translation = "The Saints and their friends are in ecstasy, knowing the Perfect Guru.", hindi = "संत साजन भए सरसे; पूरे गुर ते जाणी ॥", punjabi = "ਜੇਹੜੇ ਸੰਤ ਗੁਰਮੁਖਿ ਪੂਰੇ ਗੁਰੂ ਤੋਂ ਸਿਫ਼ਤ-ਸਾਲਾਹ ਦੀ ਬਾਣੀ ਨਾਲ ਸਾਂਝੀ ਪਾਣੀ ਸਿੱਖ ਲੈਂਦੇ ਹਨ ਉਹਨਾਂ ਦੇ ਹਿਰਦੇ ਖਿੜ ਆਉਂਦੇ ਹਨ।", wordMeaning = "ਸਰਸੇ = ਸ-ਰਸ, ਰਹੇ, ਆਨੰਦ-ਭਰਪੂਰ। ਗੁਰ ਤੇ = ਗੁਰੂ ਤੋਂ। ਸਤਿਗੁਰੁ ਰਹਿਆ", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-209", gurmukhi = "ਸੁਣਤੇ ਪੁਨੀਤ. ਕਹਤੇ ਪਵਿਤੁ; ਸਤਿਗੁਰੁ ਰਹਿਆ ਭਰਪੂਰੇ ॥", transliteration = "sunte puneet. kahte pvit; stigur rhiaa bharpoore ||", translation = "Pure are the listeners, and pure are the speakers; the True Guru is all-pervading and permeating.", hindi = "सुणते पुनीत. कहते पवितु; सतिगुरु रहिआ भरपूरे ॥", punjabi = "ਇਸ ਬਾਣੀ ਨੂੰ ਸੁਣਨ ਵਾਲੇ ਉਚਾਰਨ ਵਾਲੇ ਸਭ ਪਵਿਤ੍ਰ-ਆਤਮਕ ਹੋ ਜਾਂਦੇ ਹਨ, ਇਸ ਬਾਣੀ ਵਿਚ ਉਹਨਾਂ ਨੂੰ ਸਤਿਗੁਰੂ ਹੀ ਦਿੱਸਦਾ ਹੈ।", wordMeaning = "ਭਰਪੂਰੇ = ਗੁਰੂ (ਆਪਣੀ ਬਾਣੀ ਵਿਚ) ਭਰਪੂਰ ਹੈ, ਬਾਣੀ ਗੁਰੂ-ਰੂਪ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "anand-sahib-210", gurmukhi = "ਬਿਨਵੰਤਿ ਨਾਨਕੁ. ਗੁਰ ਚਰਣ ਲਾਗੇ; ਵਾਜੇ ਅਨਹਦ ਤੂਰੇ ॥੪੦॥੧॥", transliteration = "binavant naanak. gur charan laage; vaaje anahad toore ||40||1||", translation = "Prays Nanak, touching the Guru's Feet, the unstruck sound current of the celestial bugles vibrates and resounds. ||40||1||", hindi = "बिनवंति नानकु. गुर चरण लागे; वाजे अनहद तूरे ॥४०॥१॥", punjabi = "ਨਾਨਕ ਬੇਨਤੀ ਕਰਦਾ ਹੈ-ਜੇਹੜੇ ਬੰਦੇ ਗੁਰੂ ਦੀ ਚਰਨੀਂ ਲੱਗਦੇ ਹਨ, ਉਹਨਾਂ ਦੇ ਅੰਦਰ ਇਕ-ਰਸ (ਖ਼ੁਸ਼ੀ ਦੇ) ਵਾਜੇ ਵੱਜ ਪੈਂਦੇ ਹਨ (ਉਹਨਾਂ ਦੇ ਅੰਦਰ ਆਤਮਕ ਆਨੰਦ ਪੈਦਾ ਹੋ ਜਾਂਦਾ ਹੈ) ॥੪੦॥੧॥", wordMeaning = "ਅਨਹਦ = ਇਕ-ਰਸ। ਤੂਰੇ = ਵਾਜੇ। ਮਨੋਰਥ = ਮਨ ਦੀਆਂ ਦੌੜਾਂ ॥੪੦॥੧॥", startsAtMs = 0L, endsAtMs = 0L)
)
